-- 396: the FAQ's FFA early-leave entry - client keys, the 386 rows, and
-- machine-translation seeds.
-- KEYS: four client keys for the four strings that state the FFA early-leave grace
-- (InfoLibrary ModeFfaExt, Rewards and WhenCounts; ModeInfoText Ffa), each row as
-- tools/i18n_sync_keys.build_client_keys derives it from tools/i18n_source.json
-- (key_id = sha1("client\0" + English)[:16], source_hash, sensitive, context):
--   44732e465b16cee1 ModeFfaExt, replacing 386's 79023ff50ab9d08e;
--   6173541088dbb882 Rewards, replacing 386's 3bb08fc59139b367;
--   9d365a214640aebd WhenCounts, replacing 386's 439cd5d90ee1b6d3;
--   0ab13f648dd0175b ModeInfoText Ffa, replacing 386's 3988c8d80e42f69d.
-- THE 386 ROWS: the rows that exist for the four client keys migration 386 registered
-- for these strings (the grace in an earlier wording) are retired, and their pending
-- proposals decided 'superseded'; their entries and proposal history are kept. The
-- file RAISES, and commits nothing, if an entry on them is approved.
-- SEEDS: sixteen PENDING claude-mt proposals (es, ru, uk and sv for each key), the text
-- of the bundled plugin/I18nCatalogues.cs drafts. Every literal is one line (a line
-- break is joined in as || chr(10) || and a middle dot as || chr(183) ||), and the file
-- RAISES, and commits nothing, when a seed text does not carry its expected md5.
-- A second run writes no row.
-- After rollback_396_faq_early_leave_keys.sql, with no other pending proposal or
-- approved translation covering the sixteen pairs, applying this file again commits
-- nothing.
-- Explicit transaction (#340): four SET LOCAL lines (lock_timeout 5s,
-- idle_in_transaction_session_timeout 5s, statement_timeout 25s, synchronous_commit
-- local), then one top-level statement, a DO block.
-- DEPLOY ORDER: this file first; the batch's api deploy follows it.
-- ROLLBACK: rollback_396_faq_early_leave_keys.sql.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL idle_in_transaction_session_timeout = '5s';
SET LOCAL statement_timeout = '25s';
SET LOCAL synchronous_commit = local;

-- ALL the work is this one statement (see BOUNDS): 1. the key hash guard, 2. the four
-- keys and their post-check, 3. the 386 rows, 4. the seeds, 5. the closing post-checks.
DO $m396$
DECLARE
    clash        TEXT;
    v_ok         INT;
    v_keys       INT;
    v_approved   INT;
    v_retired    INT;
    v_superseded INT;
    v_seeded     INT;
    v_live       INT;
    v_pending    INT;
    uncovered    INT;
    sample       TEXT;
BEGIN
    -- 1. Key hash guard, ahead of step 2's INSERT: refuse an existing row at one of the
    --    four new ids whose source_hash is not the one this file writes.
    SELECT string_agg(k.key_id || CASE WHEN k.retired_at IS NULL THEN ' (live)' ELSE ' (retired)' END,
                      ', ' ORDER BY k.key_id)
      INTO clash
      FROM i18n_keys k
      JOIN (VALUES
        ('44732e465b16cee1', '6524e0bf096ed57c17761db3877b01b7f4fa9af8'),
        ('6173541088dbb882', '7593282edfd30f2f29eec43aa24bcdcbef1eee88'),
        ('9d365a214640aebd', 'd0ec9113911cb0e765862a792d3dc650658b6a0a'),
        ('0ab13f648dd0175b', 'd051e33ca0935879b78ca79817301c2f6bac8a06')
      ) AS x(key_id, source_hash) ON x.key_id = k.key_id
     WHERE k.source_hash IS DISTINCT FROM x.source_hash;
    IF clash IS NOT NULL THEN
        RAISE EXCEPTION 'migration 396: key % already present with a different source_hash; a client key_id is derived from its English, so this is a damaged row or an id collision, never a re-key; nothing committed', clash;
    END IF;

    -- 2. The four keys: inserted, or a same-hash row brought to exactly these values.
    INSERT INTO i18n_keys (key_id, namespace, msgctxt, source_hash, sensitive, max_px, context, updated_at)
    SELECT v.key_id, v.namespace, v.msgctxt, v.source_hash, v.sensitive, NULL, v.context, NOW()
      FROM (VALUES
        ('44732e465b16cee1', 'client', '<color=#FFD94D><b>HOW A PICK ACTUALLY LANDS</b></color>' || chr(10) || chr(10) || '- Confirming a card applies nothing - not even on your own screen. Every picker publishes their choice, the room master collects them and publishes one accepted list, and every client applies exactly that list in the same order. That is why all 3-10 screens always agree on who got what.' || chr(10) || '- The numbers: 45 seconds base, plus 20 more each time a pick lands near the end, capped at 90.' || chr(10) || '- The on-screen 0 is exactly the auto-confirm moment - the client confirms slightly early, so a slow connection can''t eat your pick.' || chr(10) || '- <color=#FF6666>Two rare cases still yield no card:</color> a pick published in the final instant can miss the cutoff (you get a toast saying so), and a crashed seat is finalized without one.' || chr(10) || chr(10) || '<color=#FFD94D><b>WHAT REPLACING A CARD REALLY DOES</b></color>' || chr(10) || chr(10) || '- ROUNDS has no way to subtract one card''s stats. When your oldest card rolls off, the mod fully resets your character and silently replays your surviving cards in their original order. A toast on every screen names what you lost.' || chr(10) || chr(10) || '<color=#FFD94D><b>MAP SCALING</b></color>' || chr(10) || chr(10) || '- With 5 or more players the map grows 6 percent per player above 4, capped at x1.40: five players play at x1.06, ten at x1.36. 3-4 player games are unscaled.' || chr(10) || '- The camera, the kill boundary and spawn positions all scale with it.' || chr(10) || '- Vanilla maps ship only four spawn points, so on scaled maps the mod scans the freshly loaded map for solid static ground and gives players 5-10 their own spawns instead of shared coordinates.' || chr(10) || chr(10) || '<color=#FFD94D><b>TEN PLAYERS, FOUR COLORS</b></color>' || chr(10) || chr(10) || '- ROUNDS ships exactly four body colors, so colors repeat every 4 players. Nametags keep duplicates apart, and equipped body-color cosmetics still show.' || chr(10) || '- To help you find yourself, the screen dims around your own player for the first second after each spawn - the same second in which nobody can fire or block (<color=#7FD4FF>spawn grace</color>).' || chr(10) || chr(10) || '<color=#FFD94D><b>DOUBLE KO</b></color>' || chr(10) || chr(10) || '- If the last players alive kill each other in one exchange, nobody scores and the round just ends - announced on every screen.' || chr(10) || '- The winner is decided at the very end of the frame, so a mutual kill can''t hand the round to whoever died a split second later.' || chr(10) || chr(10) || '<color=#FFD94D><b>LEAVERS, PRECISELY</b></color>' || chr(10) || chr(10) || '- A leaver''s points, half points and kills freeze at the moment they leave and still count for placement in every later report of the sitting.' || chr(10) || '- If a leaver was one of the last two standing, the survivor takes the half point.' || chr(10) || '- <color=#7FE87F>Early-leave grace:</color> leave a game before the field has scored four half points in total, whether or not any became a full point, and that game is unrated for you - no rating change, no game Gold or XP. Achievements and other earning ways are unaffected. Any later leave counts in full: leaving early doesn''t dodge the loss.' || chr(10) || '- Players who left in an EARLIER game ride along as absent ghosts - on the roster, excluded from rating and pay.' || chr(10) || '- A game that drops under 3 players before 2 half points were scored is cancelled; dropping under 3 after a game over ends the sitting.', '6524e0bf096ed57c17761db3877b01b7f4fa9af8', TRUE, CAST('InfoLibrary ' || chr(183) || ' (file scope)' AS VARCHAR(160))),
        ('6173541088dbb882', 'client', 'Every finished game pays XP, XP converts to Gold at 100 XP = 1 Gold, and ranked play multiplies the base rewards below by your opponent''s rank tier. This is the pay table - exact numbers, mode by mode. (Tournament podium prizes are separate; see <color=#7FD4FF>Deadlines & forfeits</color>.)' || chr(10) || chr(10) || '<color=#FFD94D><b>THE TIER MULTIPLIER</b></color>' || chr(10) || chr(10) || 'In ranked play, base rewards are multiplied by the OPPONENT''S rank tier - <color=#7FE87F>win or lose. Playing up always pays.</color>' || chr(10) || chr(10) || '<color=#7FD4FF>Beginner</color> (under 1500) - x1.0' || chr(10) || '<color=#7FD4FF>Intermediate</color> (1500 or more) - x1.5' || chr(10) || '<color=#7FD4FF>Advanced</color> (1675 or more) - x2.0' || chr(10) || '<color=#7FD4FF>Master</color> (1980 or more) - x2.5' || chr(10) || '<color=#7FD4FF>Grand Master</color> (2330 or more) - x3.0' || chr(10) || chr(10) || 'It applies to XP and to series Gold, and an opponent with no rating on record counts as 1500 (x1.5). Which rating is ''the opponent''s'': their 1v1 rating in 1v1, the opposing team''s average 2v2 rating in 2v2, the opposing seat''s average 1v1 rating in 1v2, and your opponents'' average FFA rating in FFA.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v1</b></color>' || chr(10) || chr(10) || 'Per game, multipliers stack, then the total truncates to a whole number:' || chr(10) || chr(10) || '- Base <color=#7FE87F>250 XP</color> per finished game, casual included.' || chr(10) || '- Game win: x1.5. Ranked: x1.5. Opponent tier: x1.0 to x3.0 (ranked only).' || chr(10) || '- A shutout win (opponent on 0 rounds) adds +100 XP flat, after the multipliers.' || chr(10) || chr(10) || 'Exact examples: casual loss 250, casual win 375; ranked loss vs a Beginner 375; ranked win vs a Beginner 562, vs an Intermediate 843, vs a Grand Master 1687 (+100 more if 5-0).' || chr(10) || chr(10) || 'Series Gold, ranked BO3 only - casual play creates no series and pays none:' || chr(10) || chr(10) || '- Loser: 5 x opponent tier, truncated. Winner: double that.' || chr(10) || '- Winner doubles AGAIN if the beaten player currently sits in the leaderboard top 3.' || chr(10) || '- +2 flat on top for a 2-0 sweep.' || chr(10) || '- Winner/loser by opponent tier, before podium and sweep: Beginner 10/5, Intermediate 14/7, Advanced 20/10, Master 24/12, Grand Master 30/15.' || chr(10) || chr(10) || '<color=#FFD94D><b>2v2</b></color>' || chr(10) || chr(10) || '- Per game: 600 XP x the opposing team''s tier, then x1.5 if your team won the game.' || chr(10) || '- Default all-1500 lobby: 900 XP for a loss, 1350 for a win.' || chr(10) || '- Series Gold: 50 (each winner) or 25 (each loser), x the opposing team''s tier. Default lobby: 75/37.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v2</b></color>' || chr(10) || chr(10) || 'Base 500 XP per game, x1.5 on a win, then a per-seat difficulty multiplier:' || chr(10) || chr(10) || '- Solo seat: x1.5.' || chr(10) || '- Solo playing WITHOUT the extra-pick handicap: another x1.20.' || chr(10) || '- Duo seats facing a buffed solo (extra pick on): x1.10.' || chr(10) || '- Opponent tier, read from the opposing seat''s average 1v1 rating - 1v2 has no rating of its own.' || chr(10) || '- Opponent currently in the 1v2 leaderboard top 3: x1.35, win or lose.' || chr(10) || '- The whole product is capped at x4.0; the x1.5 win bonus applies on top of the cap.' || chr(10) || chr(10) || 'Defaults with extra pick on: the solo earns 1125 XP for a loss and 1687 for a win; each duo member 825/1237.' || chr(10) || chr(10) || 'Series Gold: 40 (winning side) or 20 (losing side), x opponent tier only - the seat, handicap and podium factors live on XP. Default: 60/30.' || chr(10) || chr(10) || '<color=#FFD94D><b>FFA - THE METER</b></color>' || chr(10) || chr(10) || 'FFA pays for FIGHTING, not for time in the lobby. The formula, in readable form:' || chr(10) || chr(10) || '- The work unit is <color=#7FD4FF>battles</color>: every decisive round scored by anyone in the game. <color=#FF6666>Camping adds nothing to the pool</color>, and the last-place cut it earns is the smallest share of what everyone else generated.' || chr(10) || '- A pace ceiling caps how fast battles cash in. For a lobby of P players, one battle is expected about every 3.08 + 6.54 x P seconds (P counted as at least 3 and at most 6 here), and the game pays at most TWICE that pace across the game''s elapsed time on the server''s clock - stalling or point-farming cannot outrun it.' || chr(10) || '- The base rate is 3.5 Gold per player-minute, +5% for every player above 4. A 10-player FFA is the best Gold rate in the game.' || chr(10) || '- Placement shapes your cut of the pool: 1st place earns 1.666x the lobby average, last place 0.334x - about a 5x spread. Players sharing a place share the same cut.' || chr(10) || '- A stronger field multiplies the pot: your opponents'' average tier divided by 1.5, so a default 1500 field is exactly x1.0. Casual lobbies take the bottom factor (about x0.667) and never touch ratings.' || chr(10) || '- The pool is a Gold amount. 55% pays directly as Placement Gold (minimum 1). The other 45% pays as XP at 100 XP per point of pool (minimum 50 XP), which drips back as Gold through the normal conversion.' || chr(10) || '- Placement itself sorts by points, then all round wins earned (spent ones included), then kills where the lobby''s kill tiebreak is active; remaining ties share a place.' || chr(10) || '- Ghosts and graced early leavers are unrated and receive no game Gold or XP from that game: leaving before the field scored four half points in total, whether or not any became a full point, takes you out of those results. The grace leaves achievements and other earning ways unaffected.' || chr(10) || chr(10) || '<color=#FFD94D><b>LEVELS AND THE XP-TO-GOLD DRIP</b></color>' || chr(10) || chr(10) || '- XP converts at <color=#7FE87F>100 XP = 1 Gold</color>, paid every time your running total crosses a hundred mark. Every mode''s XP - tournament prizes included - feeds the same total.' || chr(10) || '- Climbing into level L costs 100 x L^1.5 XP, truncated: level 2 costs 282, level 5 costs 1118, level 10 costs 3162, level 50 costs 35355, level 100 costs 100000. Max level is 100.' || chr(10) || '- Entering a multiple-of-5 level pays bonus Gold: <color=#7FE87F>100g for levels 5 through 50, 500g for 55 through 100</color> - 6000g lifetime if you reach the cap. It lands the moment any XP award dings the level - any mode, tournament prizes included; a ding during an FFA game shows up inside that game''s +g number.' || chr(10) || chr(10) || '<color=#FFD94D><b>ACHIEVEMENT GOLD</b></color>' || chr(10) || chr(10) || 'Every achievement pays <color=#7FE87F>100g</color> unless listed here:' || chr(10) || chr(10) || '- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Grand Master (reach 2330), Touch Grass, Babel.' || chr(10) || '- <color=#7FD4FF>500g</color> - Master (reach 1980), Tag Team Sweep, Rise from the Ashes, Casual Conqueror, Twins!, Immortal, Hostile Takeover, Bodycount, Sync Champion, Async Champion.' || chr(10) || '- <color=#7FD4FF>300g</color> - Stacked Deck, Flawless, Silly Drill, Into the Deep End, Century Club, Unstoppable, Party Crasher, Heartbreak, Dragoman, Sync Finalist, Async Finalist.' || chr(10) || chr(10) || 'The FFA shutouts nest: one 5-0 win with 5 players finishing pays Clean House (100g) + Party Crasher (300g) + Hostile Takeover (500g) in a single game. The translator achievements (Rosetta, Dragoman, Babel) trigger at 10, 100 and 1000 approved live strings.' || chr(10) || chr(10) || '<color=#8A8A93>Outside matches: Discord server boosters are paid 2000g monthly, and community artists earn a 30% royalty (rounded down to whole Gold) when another player buys their item - gifts pay none.</color>', '7593282edfd30f2f29eec43aa24bcdcbef1eee88', TRUE, CAST('InfoLibrary ' || chr(183) || ' (file scope)' AS VARCHAR(160))),
        ('9d365a214640aebd', 'client', 'The rule book for what gets recorded and what gets thrown away: games, series, disconnects, bets. If a result looks missing, the reason is almost always on this page.' || chr(10) || chr(10) || '<color=#FFD94D><b>NEVER RECORDED AT ALL</b></color>' || chr(10) || chr(10) || '- Data consent off: the mod runs fully offline. Nothing is ever sent except a version check.' || chr(10) || '- Offline, practice and sandbox games: never reported by the client, and refused by the server as a backstop.' || chr(10) || '- Spectator seats submit no match record and no persistent stats. (The mod keeps local diagnostics in its own log — frames, connection facts — and sends nothing automatically; they leave your PC only inside a bug report you choose to attach logs to.)' || chr(10) || chr(10) || '<color=#FFD94D><b>RANKED OR CASUAL</b></color>' || chr(10) || chr(10) || '- Either player''s Ranked toggle off in a room-code game - it plays as CASUAL. Still fully recorded with stats and XP; it never touches rating (see <color=#7FD4FF>How games are tracked</color>).' || chr(10) || '- Opponent has never run the mod - always casual, never upgraded. (A live unfinished series from an earlier sitting is the one thing that keeps ranked status across a gap.)' || chr(10) || '- Toggling Ranked off MID-SERIES does not void the series. The running best-of-3 is your consent record; its games stay ranked.' || chr(10) || '- A game reported as casual is UPGRADED to ranked when the server can see both players are modded, both have Ranked on, and the sitting is live.' || chr(10) || '- A ranked-banned participant forces a 1v1 casual at report time - even in a queue room, even mid-series. (The other modes shut banned players out at the door instead.)' || chr(10) || '- Mod-issued rooms are consented by definition; queueing is consent. The ranked queue, 2v2 and tournaments rate; ranked FFA lobbies rate while casual ones don''t; 1v2 records without rating.' || chr(10) || chr(10) || '<color=#FFD94D><b>DISCONNECTS - 1V1</b></color>' || chr(10) || chr(10) || '- You leave a game to join a queued ranked match - the game you left is canceled: nothing recorded, no leave logged.' || chr(10) || '- Opponent DCs at 4-4 - you get the win, recorded 5-4.' || chr(10) || '- Opponent DCs while you hold 4 rounds - you get the win at the standing score.' || chr(10) || '- Any other DC - <color=#FF6666>the game is canceled and no result is recorded</color>, even when the leaver was ahead. Nobody gets a free win and nobody eats an unfair loss (the leave itself can still be logged - see below).' || chr(10) || '- Ranked leave %: a DC is logged against the leaver when the CURRENT game had meaningful play (2 or more points scored, or a completed round) and neither side was at 4 rounds. One DC per player per series. The stat is your DCs divided by your ranked series played plus your DCs.' || chr(10) || '- Casual rage quits: ANY mid-game leave in a casual 1v1 is logged, even at 4-0. It feeds the Rage Quit % stat (how often opponents walk out on you) - never rating. (A survivor already at 4 rounds still takes the casual win and its XP.)' || chr(10) || chr(10) || '<color=#FFD94D><b>DISCONNECTS - 2V2 AND FFA</b></color>' || chr(10) || chr(10) || '- 2v2: a team DCs while the other team leads the series and the abandoned game had 2 or more points - the leading team takes the whole series, with full ratings and rewards.' || chr(10) || '- Any other 2v2 DC - the series PAUSES for manual admin resolution instead of auto-deciding. If the same four re-queue within about 30 minutes, the matcher puts them back on the same series with the score kept.' || chr(10) || '- FFA keeps playing when someone leaves, as long as 2 or more remain (a game that drops under 3 players before the field scored 2 half points is cancelled instead). The leaver''s tallies are frozen, and they are still placed and rated for the game they left during - <color=#FF6666>leaving at 0 points does not dodge the loss</color>.' || chr(10) || '- FFA early-leave grace: a leaver who left before the field had scored four half points in total, whether or not any became a full point, is unrated for that game and receives no game Gold or XP from it. Achievements and other earning ways are unaffected.' || chr(10) || '- An FFA player who left in an EARLIER game rides later reports as absent, excluded from those games'' ratings and rewards.' || chr(10) || chr(10) || '<color=#FFD94D><b>SERIES: RESUME, STALL, EXPIRE</b></color>' || chr(10) || chr(10) || '- <color=#7FE87F>An undecided best-of-3 resumes with no time limit.</color> Meet the same opponent tomorrow or next week and game 1 still stands. An expiry existed once - leavers waited it out to bank rating, so it was removed.' || chr(10) || '- Rating moves ONLY when a series completes (first to 2 game wins). Games of a series that never completes keep their match rows, XP and gold; the rating change just never happens.' || chr(10) || '- A series with no game recorded 30 minutes after it was created is abandoned and its bets are refunded.' || chr(10) || '- A mid-series stall of an hour refunds the bets, but the series itself stays active and resumable.' || chr(10) || '- Tournament series are exempt from this pruning - the bracket owns their lifecycle. A tournament match decided by forfeit can''t be bet on.' || chr(10) || chr(10) || '<color=#FFD94D><b>THROWN OUT AFTER THE FACT</b></color>' || chr(10) || chr(10) || '- The one AUTOMATIC invalidation in the whole mod: a repeated pattern of implausibly short matches between the same two players inside a short window. The current match AND the earlier short ones are invalidated together, their gold and XP reversed, their series voided.' || chr(10) || '- Admin reversal: an admin can void a series - rating changes subtracted, gold clawed back, every match in it invalidated, unsettled bets refunded. Invalidated matches disappear from every board and stat.' || chr(10) || '- Quarantine (2v2 and FFA): a report that arrives for a lobby that''s no longer active isn''t deleted - it''s held for admin review, and an admin can still accept it into the record or discard it.' || chr(10) || chr(10) || '<color=#FFD94D><b>IF THE REPORT CAN''T SEND</b></color>' || chr(10) || chr(10) || '- A failed report goes to a persistent outbox: retried in the background and saved to disk, so it''s re-sent on your next launch even if you quit right after the game. You''ll see ''Couldn''t record the match - retrying in the background'', then ''Match recorded'' when it lands.' || chr(10) || '- 1v1 reporter crashes before the report exists - the surviving opponent''s disconnect path usually records the result instead.' || chr(10) || '- FFA elects its reporter among the players still present, so a crashed reporter is never elected. A winner who quits before the report is still recorded from their frozen tallies.' || chr(10) || '- A 2v2 game that ends without its series id retries the lookup and defers the send; if that also fails, the game is not recorded.', 'd0ec9113911cb0e765862a792d3dc650658b6a0a', TRUE, CAST('InfoLibrary ' || chr(183) || ' (file scope)' AS VARCHAR(160))),
        ('0ab13f648dd0175b', 'client', 'Free-for-all for 3-10 players. Every player is their own team.' || chr(10) || 'Standard ROUNDS scoring - first to {0} points takes the game.' || chr(10) || chr(10) || '<color=#FFD94D><b>HOW TO PLAY</b></color>' || chr(10) || chr(10) || '- There is no Elo band. Joining a lobby is consent to play.' || chr(10) || chr(10) || '- Create a lobby, or join an open one from the browser.' || chr(10) || '  The HOST presses Start once at least 3 players are in' || chr(10) || '  (up to 10). Several lobbies can be open at once.' || chr(10) || chr(10) || '- If the host leaves, the longest-waiting member becomes' || chr(10) || '  the new host automatically.' || chr(10) || chr(10) || '- After each point, everyone except the point winner' || chr(10) || '  picks a card at the same time.' || chr(10) || chr(10) || '- The pick timer is shown on screen. A pick landing' || chr(10) || '  near the end grants everyone a little extra time.' || chr(10) || '  When your timer hits zero, your highlighted card is' || chr(10) || '  picked for you automatically - walking away never' || chr(10) || '  skips your pick. Only a pick that misses the window' || chr(10) || '  entirely (a freeze, a crash, or the final split' || chr(10) || '  second) yields no card, with a toast saying so.' || chr(10) || chr(10) || '- You hold up to {1} cards.' || chr(10) || '  Picking one more replaces your oldest card.' || chr(10) || chr(10) || '<color=#FFD94D><b>HOST SETTINGS</b></color>' || chr(10) || chr(10) || '- The host can tune the lobby before starting: score' || chr(10) || '  target (3-10), opening draws, cards offered per' || chr(10) || '  draw (1-5), max cards held (3-5 ranked, up to 6' || chr(10) || '  casual), the Same Cards rule, and ranked/casual.' || chr(10) || chr(10) || '- Same Cards rule: everyone''s Nth card draw offers the' || chr(10) || '  SAME candidates, in the same order - if you and a rival' || chr(10) || '  were offered identical cards all game, no result can be' || chr(10) || '  blamed on draw luck. One-copy cards (like Phoenix)' || chr(10) || '  appear at most once per game for everyone.' || chr(10) || chr(10) || '- After a settings change the lobby cannot start for 60' || chr(10) || '  seconds (and briefly after someone new joins), so' || chr(10) || '  everyone can read what changed. Casual lobbies pay' || chr(10) || '  reduced rewards and never touch ratings.' || chr(10) || chr(10) || '<color=#FFD94D><b>RATING</b></color>' || chr(10) || chr(10) || '- FFA is ranked with its own Glicko rating.' || chr(10) || chr(10) || '- Placement uses points, then all round wins earned' || chr(10) || '  (spent ones included), then kills.' || chr(10) || '  Remaining ties share a place using competition' || chr(10) || '  order: 1, 2, 2, 4.' || chr(10) || chr(10) || '- Your rating is scored against the players placed' || chr(10) || '  nearest to you (up to 4 of them), so one game can''t' || chr(10) || '  swing your rating several times harder in a 10-player' || chr(10) || '  lobby than in a 3-player one. One extra comparison' || chr(10) || '  can join those four: the biggest 250+ rating gap' || chr(10) || '  that finished upside down outside them.' || chr(10) || chr(10) || '- A tied placement counts as a draw. New ratings move' || chr(10) || '  fast and settle down as you play more.' || chr(10) || chr(10) || '<color=#FFD94D><b>REWARDS</b></color>' || chr(10) || chr(10) || '- Pay is metered on the FIGHTING, not on flat per-game' || chr(10) || '  numbers: decisive rounds are the work unit, and' || chr(10) || '  elapsed time caps how fast they cash in - stall' || chr(10) || '  tactics are held to a bounded edge, and longer,' || chr(10) || '  bigger games pay more.' || chr(10) || chr(10) || '- Bigger lobbies pay a better rate per minute, and a' || chr(10) || '  10-player FFA is the best gold rate in the game.' || chr(10) || chr(10) || '- Your placement shapes your share: 1st earns about' || chr(10) || '  five times last place''s cut. Part pays as XP, part as' || chr(10) || '  Placement Gold, and a stronger opposing field' || chr(10) || '  multiplies the pot (the usual tier bonus).' || chr(10) || chr(10) || '- XP converts to Gold at 100 XP = 1 Gold, and level-ups' || chr(10) || '  pay their usual bonus Gold. A level-up landing during' || chr(10) || '  a game shows up inside that game''s +g number - that is' || chr(10) || '  how a last place can occasionally out-earn the winner.' || chr(10) || chr(10) || '- Spectators can bet Gold on FFA lobbies from this tab.' || chr(10) || chr(10) || '<color=#FFD94D><b>READING THE RECENT FFAS LIST</b></color>' || chr(10) || chr(10) || '<color=#7FD4FF>Dots + N(P)</color> - Full points won.' || chr(10) || '<color=#7FD4FF>Half dots + N(H)</color> - Round wins that' || chr(10) || '  did not become one of that player''s full points.' || chr(10) || '<color=#7FD4FF>Nk</color> - Kills.' || chr(10) || '<color=#7FD4FF>+xp +g</color> - That game''s XP and Gold' || chr(10) || '  (including any level-up bonus).' || chr(10) || '<color=#7FD4FF>Green/red number</color> - FFA rating change.' || chr(10) || '<color=#7FD4FF>Cards</color> - The hand held at game end.' || chr(10) || '  <color=#FF6666>+N replaced</color> counts picks that were' || chr(10) || '  pushed out by the card cap - hover the line to see' || chr(10) || '  every pick in order.' || chr(10) || chr(10) || '<color=#FFD94D><b>LEADERBOARD COLUMNS</b></color>' || chr(10) || chr(10) || '<color=#7FD4FF>Rank</color> - Position in the currently selected sort.' || chr(10) || '<color=#7FD4FF>Player</color> - The player''s display name.' || chr(10) || '<color=#7FD4FF>Rating</color> - The player''s separate FFA Glicko rating.' || chr(10) || '<color=#7FD4FF>Games</color> - Recorded FFA games played.' || chr(10) || '<color=#7FD4FF>Wins</color> - Games finished in 1st place.' || chr(10) || '<color=#7FD4FF>Top3</color> - Games finished in 1st, 2nd, or 3rd.' || chr(10) || '<color=#7FD4FF>AvgPl</color> - Average finishing place. Lower is' || chr(10) || '  better - 1.0 means winning every game.' || chr(10) || '<color=#7FD4FF>WR</color> - Share of games won outright.' || chr(10) || chr(10) || '<color=#FFD94D><b>GOTCHAS</b></color>' || chr(10) || chr(10) || '- Leaving mid-game is recorded. A leaver keeps their' || chr(10) || '  tallies and is placed and rated for the game they' || chr(10) || '  left - unless they left before the field had scored' || chr(10) || '  four half points in total, whether or not any became' || chr(10) || '  a full point, in which case that game does not rate' || chr(10) || '  them or pay them game Gold or XP. Achievements and' || chr(10) || '  other earning ways are unaffected.', 'd051e33ca0935879b78ca79817301c2f6bac8a06', TRUE, CAST('ModeInfoText ' || chr(183) || ' (file scope)' AS VARCHAR(160)))
      ) AS v(key_id, namespace, msgctxt, source_hash, sensitive, context)
    ON CONFLICT (key_id) DO UPDATE
       SET namespace = EXCLUDED.namespace, msgctxt = EXCLUDED.msgctxt,
           sensitive = EXCLUDED.sensitive, max_px = EXCLUDED.max_px,
           context = EXCLUDED.context, retired_at = NULL, updated_at = NOW()
     -- a same-hash row only (the key hash guard): a different-hash row stays as found and fails the post-check
     WHERE i18n_keys.source_hash = EXCLUDED.source_hash
       AND (i18n_keys.namespace, i18n_keys.msgctxt, i18n_keys.sensitive,
            i18n_keys.max_px, i18n_keys.context, i18n_keys.retired_at)
           IS DISTINCT FROM
           (EXCLUDED.namespace, EXCLUDED.msgctxt, EXCLUDED.sensitive,
            EXCLUDED.max_px, EXCLUDED.context, CAST(NULL AS TIMESTAMPTZ));
    GET DIAGNOSTICS v_keys = ROW_COUNT;

    -- Key post-check (enforcing): every new key live with the expected source text (by
    -- md5 of the stored text), hash, sensitivity and context, and no max_px.
    SELECT COUNT(*) INTO v_ok
      FROM i18n_keys k
      JOIN (VALUES
        ('44732e465b16cee1', '6524e0bf096ed57c17761db3877b01b7f4fa9af8', '6ad510377f98c7cc8cd7b6ced18f0171', TRUE, 'InfoLibrary ' || chr(183) || ' (file scope)'),
        ('6173541088dbb882', '7593282edfd30f2f29eec43aa24bcdcbef1eee88', '8a4dffe2554af0fd9e9c5d6f084399af', TRUE, 'InfoLibrary ' || chr(183) || ' (file scope)'),
        ('9d365a214640aebd', 'd0ec9113911cb0e765862a792d3dc650658b6a0a', '6ade10a23ce9f70026121031d9165d83', TRUE, 'InfoLibrary ' || chr(183) || ' (file scope)'),
        ('0ab13f648dd0175b', 'd051e33ca0935879b78ca79817301c2f6bac8a06', 'd5e3e0ca3f5f6cf269e4727bdb84b2aa', TRUE, 'ModeInfoText ' || chr(183) || ' (file scope)')
      ) AS x(key_id, source_hash, text_md5, sensitive, context) ON x.key_id = k.key_id
     WHERE k.namespace = 'client' AND k.retired_at IS NULL
       AND k.source_hash = x.source_hash AND md5(k.msgctxt) = x.text_md5
       AND k.sensitive = x.sensitive AND k.max_px IS NULL
       AND k.context IS NOT DISTINCT FROM x.context;
    IF v_ok <> 4 THEN
        RAISE EXCEPTION 'migration 396: % of 4 FAQ early-leave client keys are live with the expected source, hash, sensitivity and context; nothing committed', v_ok;
    END IF;

    -- 3. The 386 rows (see the header). Lock the four key rows in key order, then their
    --    entries, then read the approved count under those locks.
    PERFORM 1 FROM i18n_keys
     WHERE key_id IN ('3988c8d80e42f69d', '3bb08fc59139b367', '439cd5d90ee1b6d3', '79023ff50ab9d08e')
     ORDER BY key_id
       FOR NO KEY UPDATE;
    PERFORM 1 FROM i18n_entries
     WHERE key_id IN ('3988c8d80e42f69d', '3bb08fc59139b367', '439cd5d90ee1b6d3', '79023ff50ab9d08e')
     ORDER BY key_id, language_code
       FOR NO KEY UPDATE;
    SELECT COUNT(*) INTO v_approved
      FROM i18n_entries e
     WHERE e.key_id IN ('3988c8d80e42f69d', '3bb08fc59139b367', '439cd5d90ee1b6d3', '79023ff50ab9d08e')
       AND e.state = 'approved';
    IF v_approved <> 0 THEN
        RAISE EXCEPTION 'migration 396: % approved entr(ies) exist on the 386 FFA grace keys - refusing to retire translator-approved work; nothing committed', v_approved;
    END IF;
    UPDATE i18n_keys
       SET retired_at = NOW(), updated_at = NOW()
     WHERE key_id IN ('3988c8d80e42f69d', '3bb08fc59139b367', '439cd5d90ee1b6d3', '79023ff50ab9d08e')
       AND retired_at IS NULL;
    GET DIAGNOSTICS v_retired = ROW_COUNT;
    UPDATE i18n_proposals
       SET status = 'superseded', review_note = 'key retired by migration 396',
           reviewed_at = NOW()
     WHERE key_id IN ('3988c8d80e42f69d', '3bb08fc59139b367', '439cd5d90ee1b6d3', '79023ff50ab9d08e')
       AND status = 'pending';
    GET DIAGNOSTICS v_superseded = ROW_COUNT;

    -- 4. The seeds: a PENDING claude-mt draft per pair, except where IDEMPOTENT in the
    --    header says a pair gets none.
    CREATE TEMP TABLE _seed396 (
      key_id      VARCHAR(16) NOT NULL,
      lang        VARCHAR(8)  NOT NULL,
      source_hash VARCHAR(40) NOT NULL,
      target      TEXT        NOT NULL
    ) ON COMMIT DROP;

    INSERT INTO _seed396 (key_id, lang, source_hash, target) VALUES
        -- InfoLibrary ModeFfaExt (the FFA article)
        ('44732e465b16cee1', 'es', '6524e0bf096ed57c17761db3877b01b7f4fa9af8', '<color=#FFD94D><b>CÓMO ATERRIZA REALMENTE UNA ELECCIÓN</b></color>' || chr(10) || chr(10) || '- Confirmar una carta no aplica nada - ni siquiera en tu propia pantalla. Cada jugador publica su elección, el master de la sala las reúne y publica una única lista aceptada, y cada cliente aplica exactamente esa lista en el mismo orden. Por eso las 3-10 pantallas siempre coinciden en quién recibió qué.' || chr(10) || '- Los números: 45 segundos base, más 20 extra cada vez que una elección llega cerca del final, con tope en 90.' || chr(10) || '- El 0 en pantalla es exactamente el momento de autoconfirmación - el cliente confirma un poco antes, para que una conexión lenta no se coma tu elección.' || chr(10) || '- <color=#FF6666>Dos casos raros aún dejan sin carta:</color> una elección publicada en el último instante puede perder el corte (recibes un aviso que lo dice), y un asiento que se cuelga se finaliza sin carta.' || chr(10) || chr(10) || '<color=#FFD94D><b>QUÉ HACE REALMENTE REEMPLAZAR UNA CARTA</b></color>' || chr(10) || chr(10) || '- ROUNDS no tiene forma de restar las stats de una carta. Cuando tu carta más antigua sale, el mod reinicia por completo tu personaje y vuelve a aplicar en silencio tus cartas supervivientes en su orden original. Un aviso en cada pantalla nombra lo que perdiste.' || chr(10) || chr(10) || '<color=#FFD94D><b>ESCALADO DE MAPA</b></color>' || chr(10) || chr(10) || '- Con 5 o más jugadores el mapa crece un 6 por ciento por jugador por encima de 4, con tope en x1.40: cinco jugadores juegan a x1.06, diez a x1.36. Las partidas de 3-4 jugadores no se escalan.' || chr(10) || '- La cámara, el límite letal y las posiciones de aparición escalan con él.' || chr(10) || '- Los mapas vanilla traen solo cuatro puntos de aparición, así que en mapas escalados el mod escanea el mapa recién cargado en busca de suelo estático sólido y da a los jugadores 5-10 sus propias apariciones en lugar de coordenadas compartidas.' || chr(10) || chr(10) || '<color=#FFD94D><b>DIEZ JUGADORES, CUATRO COLORES</b></color>' || chr(10) || chr(10) || '- ROUNDS trae exactamente cuatro colores de cuerpo, así que los colores se repiten cada 4 jugadores. Los nombres sobre la cabeza distinguen a los duplicados, y los cosméticos de color de cuerpo equipados se siguen viendo.' || chr(10) || '- Para ayudarte a encontrarte, la pantalla se oscurece alrededor de tu propio jugador durante el primer segundo tras cada aparición - el mismo segundo en el que nadie puede disparar ni bloquear (<color=#7FD4FF>gracia de aparición</color>).' || chr(10) || chr(10) || '<color=#FFD94D><b>DOBLE KO</b></color>' || chr(10) || chr(10) || '- Si los últimos jugadores vivos se matan entre sí en un mismo intercambio, nadie puntúa y la ronda simplemente termina - anunciado en todas las pantallas.' || chr(10) || '- El ganador se decide al final exacto del frame, así que una muerte mutua no puede regalar la ronda a quien murió una fracción de segundo después.' || chr(10) || chr(10) || '<color=#FFD94D><b>LOS QUE SE VAN, CON PRECISIÓN</b></color>' || chr(10) || chr(10) || '- Los puntos, medios puntos y kills de quien se va se congelan en el momento de irse y siguen contando para el puesto en cada reporte posterior de la sesión.' || chr(10) || '- Si quien se fue era uno de los dos últimos en pie, el superviviente se lleva el medio punto.' || chr(10) || '- <color=#7FE87F>Gracia de salida temprana:</color> sal de un juego antes de que el campo haya anotado cuatro medios puntos en total, se hayan convertido o no en un punto completo, y ese juego no te puntúa - sin cambio de rating, sin oro ni XP del juego. Los logros y las demás formas de ganar no se ven afectados. Cualquier salida posterior cuenta entera: irse pronto no esquiva la derrota.' || chr(10) || '- Los jugadores que se fueron en un juego ANTERIOR siguen como fantasmas ausentes - en la lista, excluidos de rating y pago.' || chr(10) || '- Un juego que baja de 3 jugadores antes de 2 medios puntos anotados se cancela; bajar de 3 tras un fin de juego termina la sesión.'),
        ('44732e465b16cee1', 'ru', '6524e0bf096ed57c17761db3877b01b7f4fa9af8', '<color=#FFD94D><b>КАК НА САМОМ ДЕЛЕ ЗАСЧИТЫВАЕТСЯ ПИК</b></color>' || chr(10) || chr(10) || '- Подтверждение карты само по себе ничего не применяет - даже на твоём экране. Каждый пикающий публикует свой выбор, мастер комнаты собирает их и публикует один принятый список, и каждый клиент применяет ровно этот список в одном порядке. Поэтому все 3-10 экранов всегда согласны, кто что получил.' || chr(10) || '- Числа: база 45 секунд, плюс ещё 20 каждый раз, когда пик приходит под самый конец, с потолком 90.' || chr(10) || '- Ноль на экране - это ровно момент автоподтверждения: клиент подтверждает чуть заранее, чтобы медленное соединение не съело твой пик.' || chr(10) || '- <color=#FF6666>Два редких случая всё же оставляют без карты:</color> пик, опубликованный в самый последний миг, может не успеть к отсечке (об этом придёт уведомление), а упавшее место финализируется без карты.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЧТО НА САМОМ ДЕЛЕ ДЕЛАЕТ ЗАМЕНА КАРТЫ</b></color>' || chr(10) || chr(10) || '- В ROUNDS нет способа вычесть статы одной карты. Когда твоя самая старая карта уходит, мод полностью сбрасывает персонажа и молча переигрывает выжившие карты в исходном порядке. Уведомление на каждом экране называет, что ты потерял.' || chr(10) || chr(10) || '<color=#FFD94D><b>МАСШТАБИРОВАНИЕ КАРТЫ</b></color>' || chr(10) || chr(10) || '- При 5 и более игроках карта растёт на 6 процентов за каждого игрока сверх 4, с потолком x1.40: пять игроков играют на x1.06, десять - на x1.36. Игры на 3-4 игрока не масштабируются.' || chr(10) || '- Камера, смертельная граница и точки спавна масштабируются вместе с ней.' || chr(10) || '- Ванильные карты несут только четыре точки спавна, поэтому на масштабированных картах мод сканирует свежезагруженную карту на твёрдую статичную землю и выдаёт игрокам 5-10 собственные спавны вместо общих координат.' || chr(10) || chr(10) || '<color=#FFD94D><b>ДЕСЯТЬ ИГРОКОВ, ЧЕТЫРЕ ЦВЕТА</b></color>' || chr(10) || chr(10) || '- В ROUNDS ровно четыре цвета тела, так что цвета повторяются каждые 4 игрока. Неймтеги различают дублей, а надетая косметика цвета тела всё равно видна.' || chr(10) || '- Чтобы ты нашёл себя, экран затемняется вокруг твоего игрока на первую секунду после каждого спавна - ту же секунду, в которую никто не может стрелять и блокировать (<color=#7FD4FF>льгота спавна</color>).' || chr(10) || chr(10) || '<color=#FFD94D><b>ДВОЙНОЕ КО</b></color>' || chr(10) || chr(10) || '- Если последние живые игроки убивают друг друга одним обменом, никто не получает очко и раунд просто заканчивается - с объявлением на каждом экране.' || chr(10) || '- Победитель определяется в самом конце кадра, так что взаимное убийство не отдаст раунд тому, кто умер на долю секунды позже.' || chr(10) || chr(10) || '<color=#FFD94D><b>ВЫШЕДШИЕ, ТОЧНО</b></color>' || chr(10) || chr(10) || '- Очки, полуочки и убийства вышедшего замораживаются в момент выхода и всё ещё считаются для места в каждом последующем отчёте сессии.' || chr(10) || '- Если вышедший был одним из двух последних живых, полуочко берёт выживший.' || chr(10) || '- <color=#7FE87F>Льгота раннего выхода:</color> выйди из игры до того, как поле набрало в сумме четыре полуочка (ставшие полным очком или нет), - и эта игра для тебя не рейтингуется: ни изменения рейтинга, ни игрового золота, ни XP. Достижения и другие способы заработка не затрагиваются. Любой более поздний выход считается полностью: ранний выход не уворачивается от поражения.' || chr(10) || '- Игроки, вышедшие в БОЛЕЕ РАННЕЙ игре, едут дальше отсутствующими призраками - в ростере, но вне рейтинга и оплаты.' || chr(10) || '- Игра, в которой стало меньше 3 игроков до 2 набранных полуочков, отменяется; падение ниже 3 после конца игры завершает сессию.'),
        ('44732e465b16cee1', 'uk', '6524e0bf096ed57c17761db3877b01b7f4fa9af8', '<color=#FFD94D><b>ЯК НАСПРАВДІ ЗАРАХОВУЄТЬСЯ ВИБІР</b></color>' || chr(10) || chr(10) || '- Підтвердження карти саме по собі нічого не застосовує - навіть на вашому екрані. Кожен, хто обирає, публікує свій вибір, майстер кімнати збирає їх і публікує один прийнятий список, і кожен клієнт застосовує саме цей список у тому самому порядку. Тому всі 3-10 екранів завжди згодні, хто що отримав.' || chr(10) || '- Числа: базово 45 секунд, плюс іще 20 щоразу, коли чийсь вибір припадає на самий кінець, максимум 90.' || chr(10) || '- Нуль на екрані - це саме момент автопідтвердження: клієнт підтверджує трохи заздалегідь, щоб повільне з''єднання не з''їло ваш вибір.' || chr(10) || '- <color=#FF6666>Два рідкісні випадки все ж лишають без карти:</color> вибір, опублікований в останню мить, може не встигнути до відсічки (про це прийде сповіщення), а місце гравця, чия гра впала, фіналізується без карти.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЩО НАСПРАВДІ РОБИТЬ ЗАМІНА КАРТИ</b></color>' || chr(10) || chr(10) || '- У ROUNDS немає способу відняти характеристики однієї карти. Коли ваша найстаріша карта випадає, мод повністю скидає персонажа й непомітно повторно застосовує вцілілі карти в їхньому початковому порядку. Сповіщення на кожному екрані називає, що ви втратили.' || chr(10) || chr(10) || '<color=#FFD94D><b>МАСШТАБУВАННЯ МАПИ</b></color>' || chr(10) || chr(10) || '- Від 5 гравців мапа росте на 6 відсотків за кожного гравця понад 4, максимум x1.40: п''ятеро грають на x1.06, десятеро - на x1.36. Ігри на 3-4 гравців не масштабуються.' || chr(10) || '- Камера, межа вбивства й позиції спавну масштабуються разом із нею.' || chr(10) || '- Ванільні мапи мають лише чотири точки спавну, тож на масштабованих мапах мод сканує щойно завантажену мапу на тверду нерухому землю й дає гравцям 5-10 власні спавни замість спільних координат.' || chr(10) || chr(10) || '<color=#FFD94D><b>ДЕСЯТЬ ГРАВЦІВ, ЧОТИРИ КОЛЬОРИ</b></color>' || chr(10) || chr(10) || '- У ROUNDS рівно чотири кольори тіла, тож кольори повторюються кожні 4 гравці. Неймтеги розрізняють двійників, а вдягнена косметика кольору тіла все одно видима.' || chr(10) || '- Щоб ви себе знаходили, першу секунду після кожного спавну екран затемнюється довкола вашого гравця - у ту саму секунду, коли ніхто не може стріляти чи блокувати (<color=#7FD4FF>пільгова секунда спавну</color>).' || chr(10) || chr(10) || '<color=#FFD94D><b>ПОДВІЙНИЙ КО</b></color>' || chr(10) || chr(10) || '- Якщо останні живі гравці вбивають одне одного в одному обміні, очко не дістається нікому й раунд просто завершується - з оголошенням на кожному екрані.' || chr(10) || '- Переможець визначається в самому кінці кадру, тож взаємне вбивство не віддасть раунд тому, хто помер на частку секунди пізніше.' || chr(10) || chr(10) || '<color=#FFD94D><b>ПРО ТИХ, ХТО ВИЙШОВ, ТОЧНО</b></color>' || chr(10) || chr(10) || '- Очки, половинки очок і вбивства того, хто вийшов, заморожуються на момент виходу й далі рахуються для місця в кожному наступному звіті сесії.' || chr(10) || '- Якщо той, хто вийшов, був одним із двох останніх живих, половинку очка бере вцілілий.' || chr(10) || '- <color=#7FE87F>Пільга раннього виходу:</color> вийдіть із гри до того, як поле набрало загалом чотири половинки очка (що стали повним очком чи ні) - і ця гра для вас без рейтингу: ні зміни рейтингу, ні ігрового золота, ні XP. Досягнення та інші способи заробітку лишаються без змін. Будь-який пізніший вихід рахується повністю: раннім виходом поразки не уникнути.' || chr(10) || '- Гравці, що вийшли в ПОПЕРЕДНІЙ грі, їдуть далі як відсутні привиди - у складі, але поза рейтингом і оплатою.' || chr(10) || '- Гра, де стало менше 3 гравців до 2 набраних половинок очка, скасовується; якщо менше 3 стало після завершення гри - сесія закінчується.'),
        ('44732e465b16cee1', 'sv', '6524e0bf096ed57c17761db3877b01b7f4fa9af8', '<color=#FFD94D><b>HUR ETT KORTVAL FAKTISKT LANDAR</b></color>' || chr(10) || chr(10) || '- Att bekräfta ett kort applicerar ingenting - inte ens på din egen skärm. Varje väljare publicerar sitt val, rummets master samlar in dem och publicerar en accepterad lista, och varje klient applicerar exakt den listan i samma ordning. Det är därför alla 3-10 skärmar alltid är överens om vem som fick vad.' || chr(10) || '- Siffrorna: 45 sekunder som bas, plus 20 till varje gång ett val landar nära slutet, med tak vid 90.' || chr(10) || '- Nollan på skärmen är exakt ögonblicket för auto-bekräftelse - klienten bekräftar en aning tidigt, så en långsam anslutning kan inte äta upp ditt val.' || chr(10) || '- <color=#FF6666>Två sällsynta fall ger fortfarande inget kort:</color> ett val som publiceras i allra sista stund kan missa gränsen (du får en notis som säger det), och en kraschad plats slutförs utan kort.' || chr(10) || chr(10) || '<color=#FFD94D><b>VAD ETT KORTBYTE EGENTLIGEN GÖR</b></color>' || chr(10) || chr(10) || '- ROUNDS kan inte dra bort ett enskilt korts stats. När ditt äldsta kort rullar bort återställer modden din karaktär helt och spelar tyst upp dina kvarvarande kort igen i deras ursprungliga ordning. En notis på varje skärm berättar vad du förlorade.' || chr(10) || chr(10) || '<color=#FFD94D><b>KARTSKALNING</b></color>' || chr(10) || chr(10) || '- Med 5 eller fler spelare växer kartan 6 procent per spelare över 4, med tak vid x1.40: fem spelare spelar på x1.06, tio på x1.36. Matcher med 3-4 spelare skalas inte.' || chr(10) || '- Kameran, dödsgränsen och spawnpositionerna skalar allihop med.' || chr(10) || '- Originalkartorna har bara fyra spawnpunkter, så på skalade kartor skannar modden den nyladdade kartan efter fast statisk mark och ger spelare 5-10 egna spawnpunkter i stället för delade koordinater.' || chr(10) || chr(10) || '<color=#FFD94D><b>TIO SPELARE, FYRA FÄRGER</b></color>' || chr(10) || chr(10) || '- ROUNDS har exakt fyra kroppsfärger, så färgerna upprepas var 4:e spelare. Namnskyltarna håller isär dubbletter, och utrustad kroppsfärgskosmetik syns fortfarande.' || chr(10) || '- För att hjälpa dig hitta dig själv tonas skärmen ner runt din egen spelare under den första sekunden efter varje spawn - samma sekund som ingen kan skjuta eller blockera i (<color=#7FD4FF>spawnrespit</color>).' || chr(10) || chr(10) || '<color=#FFD94D><b>DUBBEL-KO</b></color>' || chr(10) || chr(10) || '- Om de sista spelarna vid liv dödar varandra i samma utväxling får ingen poäng och ronden tar bara slut - det meddelas på varje skärm.' || chr(10) || '- Vinnaren avgörs i bildrutans absoluta slut, så ett ömsesidigt dödande kan inte ge ronden till den som dog en bråkdels sekund senare.' || chr(10) || chr(10) || '<color=#FFD94D><b>AVHOPPARE, I DETALJ</b></color>' || chr(10) || chr(10) || '- En avhoppares poäng, halvpoäng och kills fryses i ögonblicket de lämnar och räknas fortfarande för placering i varje senare rapport under sittningen.' || chr(10) || '- Om en avhoppare var en av de två sista kvarstående tar överlevaren halvpoängen.' || chr(10) || '- <color=#7FE87F>Respit vid tidigt avhopp:</color> lämna en match innan fältet har tagit fyra halvpoäng sammanlagt, oavsett om någon blivit en hel poäng, så är den matchen utan rating för dig - ingen ratingförändring, inget matchguld och ingen XP. Prestationer och andra sätt att tjäna påverkas inte. Alla senare avhopp räknas fullt ut: att lämna tidigt undviker inte förlusten.' || chr(10) || '- Spelare som lämnade i en TIDIGARE match följer med som frånvarande spöken - med på rostern, undantagna från rating och betalning.' || chr(10) || '- En match som faller under 3 spelare innan 2 halvpoäng tagits ställs in; att falla under 3 efter ett matchslut avslutar sittningen.'),
        -- InfoLibrary Rewards (the economy article)
        ('6173541088dbb882', 'es', '7593282edfd30f2f29eec43aa24bcdcbef1eee88', 'Cada juego terminado paga XP, el XP se convierte en oro a 100 XP = 1 de oro, y el juego ranked multiplica las recompensas base de abajo por el rango de tu rival. Esta es la tabla de pagos - números exactos, modo por modo. (Los premios de podio de torneo van aparte; ver <color=#7FD4FF>Plazos e incomparecencias</color>.)' || chr(10) || chr(10) || '<color=#FFD94D><b>EL MULTIPLICADOR DE RANGO</b></color>' || chr(10) || chr(10) || 'En juego ranked, las recompensas base se multiplican por el rango del RIVAL - <color=#7FE87F>ganes o pierdas. Jugar hacia arriba siempre paga.</color>' || chr(10) || chr(10) || '<color=#7FD4FF>Principiante</color> (menos de 1500) - x1.0' || chr(10) || '<color=#7FD4FF>Intermedio</color> (1500 o más) - x1.5' || chr(10) || '<color=#7FD4FF>Avanzado</color> (1675 o más) - x2.0' || chr(10) || '<color=#7FD4FF>Maestro</color> (1980 o más) - x2.5' || chr(10) || '<color=#7FD4FF>Gran Maestro</color> (2330 o más) - x3.0' || chr(10) || chr(10) || 'Aplica al XP y al oro de serie, y un rival sin rating registrado cuenta como 1500 (x1.5). Cuál es ''el rating del rival'': su rating 1v1 en 1v1, el rating 2v2 medio del equipo contrario en 2v2, el rating 1v1 medio del asiento contrario en 1v2, y el rating FFA medio de tus rivales en FFA.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v1</b></color>' || chr(10) || chr(10) || 'Por juego, los multiplicadores se apilan y el total se trunca a número entero:' || chr(10) || chr(10) || '- Base de <color=#7FE87F>250 XP</color> por juego terminado, casual incluido.' || chr(10) || '- Victoria del juego: x1.5. Ranked: x1.5. Rango del rival: x1.0 a x3.0 (solo ranked).' || chr(10) || '- Una victoria por barrida (rival a 0 rondas) añade +100 XP planos, después de los multiplicadores.' || chr(10) || chr(10) || 'Ejemplos exactos: derrota casual 250, victoria casual 375; derrota ranked vs un Principiante 375; victoria ranked vs un Principiante 562, vs un Intermedio 843, vs un Gran Maestro 1687 (+100 más si es 5-0).' || chr(10) || chr(10) || 'Oro de serie, solo BO3 ranked - el juego casual no crea series y no paga ninguno:' || chr(10) || chr(10) || '- Perdedor: 5 x rango del rival, truncado. Ganador: el doble.' || chr(10) || '- El ganador dobla OTRA VEZ si el derrotado está ahora mismo en el top 3 de la clasificación.' || chr(10) || '- +2 planos encima por un 2-0.' || chr(10) || '- Ganador/perdedor por rango del rival, antes de podio y barrida: Principiante 10/5, Intermedio 14/7, Avanzado 20/10, Maestro 24/12, Gran Maestro 30/15.' || chr(10) || chr(10) || '<color=#FFD94D><b>2v2</b></color>' || chr(10) || chr(10) || '- Por juego: 600 XP x el rango del equipo contrario, luego x1.5 si tu equipo ganó el juego.' || chr(10) || '- Sala por defecto todo-1500: 900 XP por derrota, 1350 por victoria.' || chr(10) || '- Oro de serie: 50 (cada ganador) o 25 (cada perdedor), x el rango del equipo contrario. Sala por defecto: 75/37.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v2</b></color>' || chr(10) || chr(10) || 'Base de 500 XP por juego, x1.5 al ganar, y luego un multiplicador de dificultad por asiento:' || chr(10) || chr(10) || '- Asiento del solo: x1.5.' || chr(10) || '- Solo que juega SIN la ventaja de carta extra: otro x1.20.' || chr(10) || '- Asientos del dúo frente a un solo potenciado (carta extra activa): x1.10.' || chr(10) || '- Rango del rival, leído del rating 1v1 medio del asiento contrario - 1v2 no tiene rating propio.' || chr(10) || '- Rival ahora mismo en el top 3 de la clasificación 1v2: x1.35, ganes o pierdas.' || chr(10) || '- El producto entero tiene tope en x4.0; el bonus de victoria x1.5 aplica encima del tope.' || chr(10) || chr(10) || 'Por defecto con la carta extra activa: el solo gana 1125 XP por derrota y 1687 por victoria; cada miembro del dúo 825/1237.' || chr(10) || chr(10) || 'Oro de serie: 40 (lado ganador) o 20 (lado perdedor), x solo el rango del rival - el asiento, la ventaja y el podio viven en el XP. Por defecto: 60/30.' || chr(10) || chr(10) || '<color=#FFD94D><b>FFA - EL MEDIDOR</b></color>' || chr(10) || chr(10) || 'FFA paga por PELEAR, no por tiempo en la sala. La fórmula, en versión legible:' || chr(10) || chr(10) || '- La unidad de trabajo son las <color=#7FD4FF>batallas</color>: cada ronda decisiva anotada por cualquiera en el juego. <color=#FF6666>Acampar no añade nada al bote</color>, y el recorte de último puesto que gana es la parte más pequeña de lo que generaron los demás.' || chr(10) || '- Un techo de ritmo limita la velocidad a la que se cobran las batallas. Para una sala de P jugadores, se espera una batalla cada 3.08 + 6.54 x P segundos aproximadamente (P contado como mínimo 3 y máximo 6 aquí), y el juego paga como mucho el DOBLE de ese ritmo sobre el tiempo transcurrido del juego en el reloj del servidor - estancarse o farmear puntos no puede superarlo.' || chr(10) || '- La tasa base es 3.5 de oro por jugador-minuto, +5% por cada jugador por encima de 4. Un FFA de 10 jugadores es la mejor tasa de oro del juego.' || chr(10) || '- El puesto da forma a tu parte del bote: el 1.er puesto gana 1.666x la media de la sala, el último 0.334x - una horquilla de unas 5x. Los jugadores que comparten puesto comparten la misma parte.' || chr(10) || '- Un campo más fuerte multiplica el bote: el rango medio de tus rivales dividido por 1.5, así que un campo por defecto de 1500 es exactamente x1.0. Las salas casual toman el factor mínimo (unas x0.667) y nunca tocan ratings.' || chr(10) || '- El bote es una cantidad de oro. El 55% se paga directamente como Oro de puesto (mínimo 1). El otro 45% se paga como XP a 100 XP por punto de bote (mínimo 50 XP), que gotea de vuelta como oro por la conversión normal.' || chr(10) || '- El puesto en sí ordena por puntos, luego todas las rondas ganadas (las gastadas incluidas), luego kills donde el desempate por kills de la sala esté activo; los empates restantes comparten puesto.' || chr(10) || '- Los fantasmas y los que salieron pronto con gracia no puntúan ni reciben oro ni XP de ese juego: irse antes de que el campo anotara cuatro medios puntos en total, se hayan convertido o no en un punto completo, te saca de esos resultados. La gracia no afecta a los logros ni a las demás formas de ganar.' || chr(10) || chr(10) || '<color=#FFD94D><b>NIVELES Y EL GOTEO DE XP A ORO</b></color>' || chr(10) || chr(10) || '- El XP se convierte a <color=#7FE87F>100 XP = 1 de oro</color>, pagado cada vez que tu total acumulado cruza una centena. El XP de todos los modos - premios de torneo incluidos - alimenta el mismo total.' || chr(10) || '- Subir al nivel L cuesta 100 x L^1.5 XP, truncado: el nivel 2 cuesta 282, el 5 cuesta 1118, el 10 cuesta 3162, el 50 cuesta 35355, el 100 cuesta 100000. El nivel máximo es 100.' || chr(10) || '- Entrar en un nivel múltiplo de 5 paga oro extra: <color=#7FE87F>100g para los niveles 5 a 50, 500g para los 55 a 100</color> - 6000g de por vida si llegas al tope. Cae en el momento en que cualquier XP dispara el nivel - cualquier modo, premios de torneo incluidos; una subida durante un juego FFA aparece dentro del +g de ese juego.' || chr(10) || chr(10) || '<color=#FFD94D><b>ORO DE LOGROS</b></color>' || chr(10) || chr(10) || 'Cada logro paga <color=#7FE87F>100g</color> salvo que esté listado aquí:' || chr(10) || chr(10) || '- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Gran Maestro (llegar a 2330), Touch Grass, Babel.' || chr(10) || '- <color=#7FD4FF>500g</color> - Maestro (llegar a 1980), Barrida en equipo, Renacer de las cenizas, Conquistador casual, ¡Gemelos!, Inmortal, Adquisición hostil, Bajas, Campeón Sync, Campeón Async.' || chr(10) || '- <color=#7FD4FF>300g</color> - Baraja trucada, Impecable, Silly Drill, De cabeza a lo hondo, Club de los cien, Imparable, Aguafiestas, Corazón roto, Dragomán, Finalista Sync, Finalista Async.' || chr(10) || chr(10) || 'Los 5-0 de FFA se anidan: una victoria 5-0 con 5 jugadores que terminan paga Limpieza general (100g) + Aguafiestas (300g) + Adquisición hostil (500g) en un solo juego. Los logros de traductor (Rosetta, Dragomán, Babel) se disparan a las 10, 100 y 1000 cadenas vivas aprobadas.' || chr(10) || chr(10) || '<color=#8A8A93>Fuera de las partidas: los boosters del servidor de Discord cobran 2000g mensuales, y los artistas de la comunidad ganan un 30% de comisión (redondeada hacia abajo a oro entero) cuando otro jugador compra su pieza - los regalos no pagan.</color>'),
        ('6173541088dbb882', 'ru', '7593282edfd30f2f29eec43aa24bcdcbef1eee88', 'Каждая завершённая игра платит XP, XP конвертируется в золото по курсу 100 XP = 1 золото, а рейтинговая игра умножает базовые награды ниже на тир ранга соперника. Это таблица оплаты - точные числа, режим за режимом. (Призы турнирного подиума отдельно; см. <color=#7FD4FF>Дедлайны и техпоражения</color>.)' || chr(10) || chr(10) || '<color=#FFD94D><b>МНОЖИТЕЛЬ ТИРА</b></color>' || chr(10) || chr(10) || 'В рейтинговой игре базовые награды умножаются на тир ранга СОПЕРНИКА - <color=#7FE87F>при победе и при поражении. Играть вверх всегда выгодно.</color>' || chr(10) || chr(10) || '<color=#7FD4FF>Новичок</color> (ниже 1500) - x1.0' || chr(10) || '<color=#7FD4FF>Средний</color> (1500 и выше) - x1.5' || chr(10) || '<color=#7FD4FF>Продвинутый</color> (1675 и выше) - x2.0' || chr(10) || '<color=#7FD4FF>Мастер</color> (1980 и выше) - x2.5' || chr(10) || '<color=#7FD4FF>Грандмастер</color> (2330 и выше) - x3.0' || chr(10) || chr(10) || 'Он применяется к XP и к золоту за серию, а соперник без рейтинга считается за 1500 (x1.5). Чей рейтинг считается «рейтингом соперника»: его рейтинг 1v1 в 1v1, средний рейтинг 2v2 команды соперников в 2v2, средний рейтинг 1v1 противоположной стороны в 1v2 и средний рейтинг FFA твоих соперников в FFA.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v1</b></color>' || chr(10) || chr(10) || 'За игру, множители стакаются, затем итог усекается до целого:' || chr(10) || chr(10) || '- База <color=#7FE87F>250 XP</color> за завершённую игру, включая казуальные.' || chr(10) || '- Победа в игре: x1.5. Рейтинговая: x1.5. Тир соперника: от x1.0 до x3.0 (только в рейтинге).' || chr(10) || '- Сухая победа (соперник на 0 раундов) добавляет плоские +100 XP, после множителей.' || chr(10) || chr(10) || 'Точные примеры: казуальное поражение 250, казуальная победа 375; рейтинговое поражение Новичку 375; рейтинговая победа над Новичком 562, над Средним 843, над Грандмастером 1687 (+100 сверху при 5-0).' || chr(10) || chr(10) || 'Золото за серию, только рейтинговый BO3 - казуальная игра серий не создаёт и золота не платит:' || chr(10) || chr(10) || '- Проигравший: 5 x тир соперника, усечённо. Победитель: вдвое больше.' || chr(10) || '- Победитель удваивает ЕЩЁ РАЗ, если побеждённый сейчас сидит в топ-3 таблицы лидеров.' || chr(10) || '- Плоские +2 сверху за сухие 2-0.' || chr(10) || '- Победитель/проигравший по тиру соперника, до подиума и 2-0: Новичок 10/5, Средний 14/7, Продвинутый 20/10, Мастер 24/12, Грандмастер 30/15.' || chr(10) || chr(10) || '<color=#FFD94D><b>2v2</b></color>' || chr(10) || chr(10) || '- За игру: 600 XP x тир команды соперников, затем x1.5, если твоя команда выиграла игру.' || chr(10) || '- Стандартное лобби всех-по-1500: 900 XP за поражение, 1350 за победу.' || chr(10) || '- Золото за серию: 50 (каждому победителю) или 25 (каждому проигравшему), x тир команды соперников. Стандартное лобби: 75/37.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v2</b></color>' || chr(10) || chr(10) || 'База 500 XP за игру, x1.5 при победе, затем множитель сложности на слот:' || chr(10) || chr(10) || '- Слот соло: x1.5.' || chr(10) || '- Соло, играющий БЕЗ гандикапа доп. пика: ещё x1.20.' || chr(10) || '- Слоты дуо против усиленного соло (доп. пик включён): x1.10.' || chr(10) || '- Тир соперника читается из среднего рейтинга 1v1 противоположной стороны - у 1v2 нет собственного рейтинга.' || chr(10) || '- Соперник сейчас в топ-3 таблицы 1v2: x1.35, при победе и поражении.' || chr(10) || '- Всё произведение ограничено x4.0; бонус за победу x1.5 идёт поверх потолка.' || chr(10) || chr(10) || 'Стандартно при включённом доп. пике: соло получает 1125 XP за поражение и 1687 за победу; каждый в дуо - 825/1237.' || chr(10) || chr(10) || 'Золото за серию: 40 (победившая сторона) или 20 (проигравшая), x только тир соперника - факторы места, гандикапа и подиума живут на XP. Стандартно: 60/30.' || chr(10) || chr(10) || '<color=#FFD94D><b>FFA - СЧЁТЧИК</b></color>' || chr(10) || chr(10) || 'FFA платит за ДРАКУ, а не за время в лобби. Формула, в читаемом виде:' || chr(10) || chr(10) || '- Единица работы - <color=#7FD4FF>битвы</color>: каждый решающий раунд, взятый кем угодно в игре. <color=#FF6666>Кемпинг ничего не добавляет в банк</color>, а срез последнего места, который он приносит, - наименьшая доля того, что нагенерировали остальные.' || chr(10) || '- Потолок темпа ограничивает скорость обналичивания битв. Для лобби из P игроков одна битва ожидается примерно каждые 3.08 + 6.54 x P секунд (P здесь берётся не меньше 3 и не больше 6), и игра платит максимум за ВДВОЕ больший темп по прошедшему времени на часах сервера - затяжка или фарм очков его не обгонят.' || chr(10) || '- Базовая ставка - 3.5 золота за игроко-минуту, +5% за каждого игрока сверх 4. FFA на 10 игроков - лучший курс золота в игре.' || chr(10) || '- Место формирует твою долю банка: 1-е место получает 1.666x среднего по лобби, последнее - 0.334x, разброс примерно в 5 раз. Делящие место делят одинаковую долю.' || chr(10) || '- Более сильное поле умножает котёл: средний тир твоих соперников, делённый на 1.5, так что стандартное поле 1500 - ровно x1.0. Казуальные лобби берут нижний фактор (около x0.667) и рейтинги не трогают вовсе.' || chr(10) || '- Банк - это сумма золота. 55% платится напрямую как золото за место (минимум 1). Остальные 45% платятся как XP по 100 XP за очко банка (минимум 50 XP), которые обычной конверсией капают обратно золотом.' || chr(10) || '- Само место сортируется по очкам, затем по всем заработанным выигранным раундам (включая потраченные), затем по убийствам там, где в лобби включён тайбрейк по убийствам; оставшиеся ничьи делят место.' || chr(10) || '- Призраки и вышедшие рано по льготе за ту игру не рейтингуются и не получают ни игрового золота, ни XP: выход до того, как поле набрало в сумме четыре полуочка (ставшие полным очком или нет), выводит из этих итогов. Льгота не затрагивает достижения и другие способы заработка.' || chr(10) || chr(10) || '<color=#FFD94D><b>УРОВНИ И КАПЕЛЬНИЦА XP-В-ЗОЛОТО</b></color>' || chr(10) || chr(10) || '- XP конвертируется по курсу <color=#7FE87F>100 XP = 1 золото</color> и выплачивается каждый раз, когда твоя сумма пересекает сотню. XP каждого режима - включая турнирные призы - питает один общий счёт.' || chr(10) || '- Подъём на уровень L стоит 100 x L^1.5 XP, усечённо: уровень 2 стоит 282, уровень 5 - 1118, уровень 10 - 3162, уровень 50 - 35355, уровень 100 - 100000. Максимальный уровень - 100.' || chr(10) || '- Вход на уровень, кратный 5, платит бонусное золото: <color=#7FE87F>100g за уровни с 5 по 50, 500g за 55-100</color> - 6000g за всю жизнь, если добраться до потолка. Оно падает в момент, когда любая награда XP пробивает уровень - в любом режиме, включая турнирные призы; уровень, взятый во время игры FFA, попадает внутрь числа +g этой игры.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЗОЛОТО ЗА ДОСТИЖЕНИЯ</b></color>' || chr(10) || chr(10) || 'Каждое достижение платит <color=#7FE87F>100g</color>, если не указано здесь:' || chr(10) || chr(10) || '- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Грандмастер (достигни 2330), Потрогай траву, Вавилон.' || chr(10) || '- <color=#7FD4FF>500g</color> - Мастер (достигни 1980), Командный разгром, Восставший из пепла, Покоритель казуала, Близнецы!, Бессмертный, Враждебное поглощение, Убийства, Чемпион Sync, Чемпион Async.' || chr(10) || '- <color=#7FD4FF>300g</color> - Краплёная колода, Безупречный, Silly Drill, С головой в омут, Клуб сотни, Неудержимый, Незваный гость, Разбитое сердце, Драгоман, Финалист Sync, Финалист Async.' || chr(10) || chr(10) || 'Сухие победы FFA вложены: одна победа 5-0, где доиграли 5 игроков, платит Генеральную уборку (100g) + Незваного гостя (300g) + Враждебное поглощение (500g) за одну игру. Достижения переводчика (Розетта, Драгоман, Вавилон) срабатывают на 10, 100 и 1000 одобренных живых строк.' || chr(10) || chr(10) || '<color=#8A8A93>Вне матчей: бустеры Discord-сервера получают 2000g ежемесячно, а художники сообщества - роялти 30% (округляется вниз до целого золота), когда их предмет покупает другой игрок; подарки не платят ничего.</color>'),
        ('6173541088dbb882', 'uk', '7593282edfd30f2f29eec43aa24bcdcbef1eee88', 'Кожна дограна гра платить XP, XP конвертується в золото за курсом 100 XP = 1 золото, а рейтингова гра множить базові нагороди нижче на рівень рангу суперника. Це таблиця виплат - точні числа, режим за режимом. (Турнірні призи п''єдесталу окремо; див. <color=#7FD4FF>Дедлайни й технічні поразки</color>.)' || chr(10) || chr(10) || '<color=#FFD94D><b>МНОЖНИК РІВНЯ</b></color>' || chr(10) || chr(10) || 'У рейтинговій грі базові нагороди множаться на рівень рангу СУПЕРНИКА - <color=#7FE87F>перемога чи поразка. Грати проти сильніших завжди вигідно.</color>' || chr(10) || chr(10) || '<color=#7FD4FF>Початківець</color> (менше 1500) - x1.0' || chr(10) || '<color=#7FD4FF>Середній</color> (1500 і більше) - x1.5' || chr(10) || '<color=#7FD4FF>Просунутий</color> (1675 і більше) - x2.0' || chr(10) || '<color=#7FD4FF>Майстер</color> (1980 і більше) - x2.5' || chr(10) || '<color=#7FD4FF>Грандмайстер</color> (2330 і більше) - x3.0' || chr(10) || chr(10) || 'Він застосовується до XP і до золота за серію, а суперник без рейтингу в записах рахується як 1500 (x1.5). Що вважається «рейтингом суперника»: його рейтинг 1v1 в 1v1, середній рейтинг 2v2 команди суперників у 2v2, середній рейтинг 1v1 протилежного місця в 1v2 і середній рейтинг FFA ваших суперників у FFA.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v1</b></color>' || chr(10) || chr(10) || 'За гру множники стакаються, потім сума обрізається до цілого:' || chr(10) || chr(10) || '- База <color=#7FE87F>250 XP</color> за дограну гру, включно зі звичайними.' || chr(10) || '- Перемога в грі: x1.5. Рейтингова: x1.5. Рівень суперника: від x1.0 до x3.0 (лише рейтингові).' || chr(10) || '- Суха перемога (суперник на 0 раундів) додає рівно +100 XP після множників.' || chr(10) || chr(10) || 'Точні приклади: звичайна поразка 250, звичайна перемога 375; рейтингова поразка проти Початківця 375; рейтингова перемога проти Початківця 562, проти Середнього 843, проти Грандмайстра 1687 (+100 зверху за 5-0).' || chr(10) || chr(10) || 'Золото за серію, лише рейтингові BO3 - звичайна гра серій не створює і золота за них не платить:' || chr(10) || chr(10) || '- Переможений: 5 x рівень суперника, обрізано до цілого. Переможець: удвічі більше.' || chr(10) || '- Переможець подвоює ЩЕ РАЗ, якщо переможений зараз сидить у топ-3 таблиці лідерів.' || chr(10) || '- Рівно +2 зверху за суху серію 2-0.' || chr(10) || '- Переможець/переможений за рівнем суперника, до п''єдесталу й 2-0: Початківець 10/5, Середній 14/7, Просунутий 20/10, Майстер 24/12, Грандмайстер 30/15.' || chr(10) || chr(10) || '<color=#FFD94D><b>2v2</b></color>' || chr(10) || chr(10) || '- За гру: 600 XP x рівень команди суперників, потім x1.5, якщо ваша команда виграла гру.' || chr(10) || '- Стандартне лобі всіх-по-1500: 900 XP за поразку, 1350 за перемогу.' || chr(10) || '- Золото за серію: 50 (кожному переможцю) або 25 (кожному переможеному), x рівень команди суперників. Стандартне лобі: 75/37.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v2</b></color>' || chr(10) || chr(10) || 'База 500 XP за гру, x1.5 за перемогу, потім множник складності за місцем:' || chr(10) || chr(10) || '- Місце соло: x1.5.' || chr(10) || '- Соло, що грає БЕЗ фори додаткового вибору: ще x1.20.' || chr(10) || '- Місця дуо проти підсиленого соло (додатковий вибір увімкнено): x1.10.' || chr(10) || '- Рівень суперника береться із середнього рейтингу 1v1 протилежного місця - власного рейтингу в 1v2 немає.' || chr(10) || '- Суперник зараз у топ-3 таблиці лідерів 1v2: x1.35, перемога чи поразка.' || chr(10) || '- Увесь добуток обмежено x4.0; бонус за перемогу x1.5 діє поверх ліміту.' || chr(10) || chr(10) || 'Стандартно з увімкненим додатковим вибором: соло заробляє 1125 XP за поразку і 1687 за перемогу; кожен із дуо 825/1237.' || chr(10) || chr(10) || 'Золото за серію: 40 (стороні-переможцю) або 20 (стороні, що програла), лише x рівень суперника - множники місця, фори й п''єдесталу живуть на XP. Стандартно: 60/30.' || chr(10) || chr(10) || '<color=#FFD94D><b>FFA - ЛІЧИЛЬНИК</b></color>' || chr(10) || chr(10) || 'FFA платить за БОРОТЬБУ, а не за час у лобі. Формула в читабельному вигляді:' || chr(10) || chr(10) || '- Одиниця роботи - <color=#7FD4FF>битви</color>: кожен вирішальний раунд, зарахований будь-ким у грі. <color=#FF6666>Кемпінг нічого не додає в банк</color>, а частка останнього місця, яку він заробляє, - найменший шматок згенерованого рештою.' || chr(10) || '- Стеля темпу обмежує, як швидко битви переводяться в гроші. Для лобі з P гравців одна битва очікується приблизно кожні 3.08 + 6.54 x P секунд (P тут береться щонайменше 3 і щонайбільше 6), і гра платить щонайбільше ПОДВІЙНИЙ такий темп за час гри на годиннику сервера - затягування чи фарм очок його не обженуть.' || chr(10) || '- Базовий курс - 3.5 золота за гравцехвилину, +5% за кожного гравця понад 4. FFA на 10 гравців - найкращий курс золота в грі.' || chr(10) || '- Місце формує вашу частку банку: 1-ше заробляє 1.666x середнього по лобі, останнє - 0.334x - розкид приблизно в 5 разів. Гравці, що ділять місце, ділять і частку.' || chr(10) || '- Сильніший склад множить банк: середній рівень ваших суперників, поділений на 1.5, тож стандартне поле 1500 - рівно x1.0. Звичайні лобі беруть нижній множник (близько x0.667) і рейтингів не чіпають.' || chr(10) || '- Банк - це сума золота. 55% виплачується напряму як золото за місце (мінімум 1). Решта 45% платиться як XP по 100 XP за одиницю банку (мінімум 50 XP) і скрапує назад золотом через звичайну конвертацію.' || chr(10) || '- Саме місце сортується за очками, далі за всіма виграними раундами (включно з витраченими), далі за вбивствами там, де в лобі активний тай-брейк за вбивствами; нерозв''язані нічиї ділять місце.' || chr(10) || '- Привиди й ті, хто вийшов рано під пільгу, за ту гру не отримують ні рейтингу, ні ігрового золота, ні XP: вихід до того, як поле набрало загалом чотири половинки очка (що стали повним очком чи ні), виводить вас із цих підсумків. Пільга не зачіпає досягнення та інші способи заробітку.' || chr(10) || chr(10) || '<color=#FFD94D><b>РІВНІ ТА КРАПЛИНИ XP-В-ЗОЛОТО</b></color>' || chr(10) || chr(10) || '- XP конвертується за курсом <color=#7FE87F>100 XP = 1 золото</color> і платиться щоразу, коли ваша поточна сума перетинає сотню. XP кожного режиму - включно з турнірними призами - живить ту саму суму.' || chr(10) || '- Підйом на рівень L коштує 100 x L^1.5 XP, обрізано до цілого: рівень 2 коштує 282, рівень 5 - 1118, рівень 10 - 3162, рівень 50 - 35355, рівень 100 - 100000. Максимальний рівень - 100.' || chr(10) || '- Вхід на рівень, кратний 5, платить бонусне золото: <color=#7FE87F>100g за рівні з 5 по 50, 500g з 55 по 100</color> - 6000g за весь час, якщо дійдете до стелі. Воно падає в мить, коли будь-яка нагорода XP пробиває рівень - у будь-якому режимі, включно з турнірними призами; рівень, узятий під час гри FFA, показується всередині +g тієї гри.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЗОЛОТО ЗА ДОСЯГНЕННЯ</b></color>' || chr(10) || chr(10) || 'Кожне досягнення платить <color=#7FE87F>100g</color>, крім перелічених тут:' || chr(10) || chr(10) || '- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Грандмайстер (досягти 2330), Торкніться трави, Вавилон.' || chr(10) || '- <color=#7FD4FF>500g</color> - Майстер (досягти 1980), Командний розгром, Повсталий з попелу, Підкорювач звичайних, Близнюки!, Безсмертний, Вороже поглинання, Убивства, Чемпіон Sync, Чемпіон Async.' || chr(10) || '- <color=#7FD4FF>300g</color> - Підтасована колода, Бездоганний, Silly Drill, З головою у вир, Клуб сотні, Нестримний, Незваний гість, Розбите серце, Драгоман, Фіналіст Sync, Фіналіст Async.' || chr(10) || chr(10) || 'Сухі перемоги FFA вкладені: одна перемога 5-0, де дограли 5 гравців, платить Генеральне прибирання (100g) + Незваний гість (300g) + Вороже поглинання (500g) за одну гру. Досягнення перекладача (Розетта, Драгоман, Вавилон) спрацьовують на 10, 100 і 1000 схвалених живих рядків.' || chr(10) || chr(10) || '<color=#8A8A93>Поза матчами: бустери сервера Discord отримують 2000g щомісяця, а художники спільноти заробляють роялті 30% (округлені вниз до цілого золота), коли їхній предмет купує інший гравець - подарунки не платять нічого.</color>'),
        ('6173541088dbb882', 'sv', '7593282edfd30f2f29eec43aa24bcdcbef1eee88', 'Varje avslutad match betalar XP, XP omvandlas till guld enligt 100 XP = 1 guld, och Ranked-spel multiplicerar basbelöningarna nedan med din motståndares ranktier. Detta är betaltabellen - exakta siffror, läge för läge. (Turneringarnas pallpriser är separata; se <color=#7FD4FF>Deadlines & walkover</color>.)' || chr(10) || chr(10) || '<color=#FFD94D><b>TIERMULTIPLIKATORN</b></color>' || chr(10) || chr(10) || 'I Ranked-spel multipliceras basbelöningarna med MOTSTÅNDARENS ranktier - <color=#7FE87F>oavsett vinst eller förlust. Att spela uppåt lönar sig alltid.</color>' || chr(10) || chr(10) || '<color=#7FD4FF>Nybörjare</color> (under 1500) - x1.0' || chr(10) || '<color=#7FD4FF>Medel</color> (1500 eller mer) - x1.5' || chr(10) || '<color=#7FD4FF>Avancerad</color> (1675 eller mer) - x2.0' || chr(10) || '<color=#7FD4FF>Mästare</color> (1980 eller mer) - x2.5' || chr(10) || '<color=#7FD4FF>Stormästare</color> (2330 eller mer) - x3.0' || chr(10) || chr(10) || 'Den gäller XP och serieguld, och en motståndare utan registrerad rating räknas som 1500 (x1.5). Vad som är ''motståndarens'' rating: deras 1v1-rating i 1v1, motståndarlagets snitt-2v2-rating i 2v2, motståndarsidans snitt-1v1-rating i 1v2, och dina motståndares snitt-FFA-rating i FFA.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v1</b></color>' || chr(10) || chr(10) || 'Per match, multiplikatorerna staplas, sedan trunkeras totalen till ett heltal:' || chr(10) || chr(10) || '- Bas <color=#7FE87F>250 XP</color> per avslutad match, casual inräknat.' || chr(10) || '- Matchvinst: x1.5. Ranked: x1.5. Motståndartier: x1.0 till x3.0 (endast Ranked).' || chr(10) || '- En utklassningsvinst (motståndaren på 0 ronder) ger +100 XP platt, efter multiplikatorerna.' || chr(10) || chr(10) || 'Exakta exempel: casual-förlust 250, casual-vinst 375; Ranked-förlust mot en Nybörjare 375; Ranked-vinst mot en Nybörjare 562, mot en Medel 843, mot en Stormästare 1687 (+100 till vid 5-0).' || chr(10) || chr(10) || 'Serieguld, endast Ranked-BO3 - casual-spel skapar ingen serie och betalar inget:' || chr(10) || chr(10) || '- Förloraren: 5 x motståndartier, trunkerat. Vinnaren: det dubbla.' || chr(10) || '- Vinnaren dubblar IGEN om den besegrade spelaren just nu sitter i topplistans topp 3.' || chr(10) || '- +2 platt ovanpå för en 2-0-svepning.' || chr(10) || '- Vinnare/förlorare per motståndartier, före pall och svep: Nybörjare 10/5, Medel 14/7, Avancerad 20/10, Mästare 24/12, Stormästare 30/15.' || chr(10) || chr(10) || '<color=#FFD94D><b>2v2</b></color>' || chr(10) || chr(10) || '- Per match: 600 XP x motståndarlagets tier, sedan x1.5 om ditt lag vann matchen.' || chr(10) || '- Standardlobby där alla ligger på 1500: 900 XP för en förlust, 1350 för en vinst.' || chr(10) || '- Serieguld: 50 (varje vinnare) eller 25 (varje förlorare), x motståndarlagets tier. Standardlobby: 75/37.' || chr(10) || chr(10) || '<color=#FFD94D><b>1v2</b></color>' || chr(10) || chr(10) || 'Bas 500 XP per match, x1.5 vid vinst, sedan en svårighetsmultiplikator per plats:' || chr(10) || chr(10) || '- Soloplatsen: x1.5.' || chr(10) || '- Solo som spelar UTAN extraval-handikappet: ytterligare x1.20.' || chr(10) || '- Duoplatser som möter en buffad solo (extraval på): x1.10.' || chr(10) || '- Motståndartier, läst från motståndarsidans snitt-1v1-rating - 1v2 har ingen egen rating.' || chr(10) || '- Motståndare som just nu är i 1v2-topplistans topp 3: x1.35, oavsett vinst eller förlust.' || chr(10) || '- Hela produkten har ett tak på x4.0; vinstbonusen x1.5 appliceras ovanpå taket.' || chr(10) || chr(10) || 'Standardvärden med extraval på: solospelaren tjänar 1125 XP för en förlust och 1687 för en vinst; varje duomedlem 825/1237.' || chr(10) || chr(10) || 'Serieguld: 40 (vinnande sidan) eller 20 (förlorande sidan), x enbart motståndartier - plats-, handikapp- och pallfaktorerna ligger på XP:n. Standard: 60/30.' || chr(10) || chr(10) || '<color=#FFD94D><b>FFA - MÄTAREN</b></color>' || chr(10) || chr(10) || 'FFA betalar för STRIDEN, inte för tid i lobbyn. Formeln, i läsbar form:' || chr(10) || chr(10) || '- Arbetsenheten är <color=#7FD4FF>strider</color>: varje avgörande rond som någon i matchen vinner. <color=#FF6666>Campande tillför inget till potten</color>, och sistaplatsandelen det ger är den minsta andelen av vad alla andra genererade.' || chr(10) || '- Ett taktak begränsar hur snabbt strider kan lösas in. För en lobby med P spelare förväntas en strid ungefär var 3.08 + 6.54 x P sekund (P räknas som minst 3 och högst 6 här), och matchen betalar som mest för DUBBLA den takten över matchens förflutna tid på serverns klocka - att förhala eller poängfarma kan inte springa ifrån det.' || chr(10) || '- Basnivån är 3.5 guld per spelarminut, +5% för varje spelare över 4. En 10-spelar-FFA är den bästa guldtakten i spelet.' || chr(10) || '- Placeringen formar din andel av potten: 1:a plats tjänar 1.666x lobbysnittet, sista plats 0.334x - ungefär en 5x spridning. Spelare som delar placering delar samma andel.' || chr(10) || '- Ett starkare fält multiplicerar potten: dina motståndares snitt-tier delat med 1.5, så ett standardfält på 1500 är exakt x1.0. Casual-lobbyer tar bottenfaktorn (ungefär x0.667) och rör aldrig ratingar.' || chr(10) || '- Potten är ett guldbelopp. 55% betalas direkt som placeringsguld (minst 1). Övriga 45% betalas som XP med 100 XP per pottpoäng (minst 50 XP), vilket droppar tillbaka som guld genom den vanliga omvandlingen.' || chr(10) || '- Själva placeringen sorterar på poäng, sedan alla intjänade rondvinster (även spenderade), sedan kills där lobbyns kill-tiebreak är aktiv; kvarvarande oavgjorda delar placering.' || chr(10) || '- Spöken och tidiga avhoppare med respit får varken rating, matchguld eller XP för den matchen: att lämna innan fältet tagit fyra halvpoäng sammanlagt, oavsett om någon blivit en hel poäng, tar dig ur de resultaten. Respiten påverkar inte prestationer och andra sätt att tjäna.' || chr(10) || chr(10) || '<color=#FFD94D><b>NIVÅER OCH XP-TILL-GULD-DROPPET</b></color>' || chr(10) || chr(10) || '- XP omvandlas enligt <color=#7FE87F>100 XP = 1 guld</color>, utbetalt varje gång din löpande total passerar ett hundratal. Varje läges XP - turneringspriser inräknade - matar samma total.' || chr(10) || '- Att klättra till nivå L kostar 100 x L^1.5 XP, trunkerat: nivå 2 kostar 282, nivå 5 kostar 1118, nivå 10 kostar 3162, nivå 50 kostar 35355, nivå 100 kostar 100000. Maxnivån är 100.' || chr(10) || '- Att gå in i en nivå delbar med 5 betalar bonusguld: <color=#7FE87F>100g för nivå 5 till 50, 500g för 55 till 100</color> - 6000g över en livstid om du når taket. Det landar i samma ögonblick som någon XP-utdelning dinger nivån - vilket läge som helst, turneringspriser inräknade; en ding under en FFA-match syns inne i den matchens +g-siffra.' || chr(10) || chr(10) || '<color=#FFD94D><b>PRESTATIONSGULD</b></color>' || chr(10) || chr(10) || 'Varje prestation betalar <color=#7FE87F>100g</color> om den inte listas här:' || chr(10) || chr(10) || '- <color=#7FD4FF>1000g</color> - Sid Slayer, Stan Slayer, Stormästare (nå 2330), Touch Grass, Babel.' || chr(10) || '- <color=#7FD4FF>500g</color> - Mästare (nå 1980), Lagutklassning, Upp ur askan, Casual-erövrare, Tvillingar!, Odödlig, Fientligt övertagande, Dödstal, Sync-mästare, Async-mästare.' || chr(10) || '- <color=#7FD4FF>300g</color> - Riggad kortlek, Felfri, Silly Drill, Ut på djupt vatten, Hundraklubben, Ostoppbar, Objuden gäst, Krossat hjärta, Dragoman, Sync-finalist, Async-finalist.' || chr(10) || chr(10) || 'FFA-utklassningarna är nästlade: en 5-0-vinst med 5 spelare som spelar klart betalar Storstädning (100g) + Objuden gäst (300g) + Fientligt övertagande (500g) i en enda match. Översättarprestationerna (Rosetta, Dragoman, Babel) utlöses vid 10, 100 och 1000 godkända live-strängar.' || chr(10) || chr(10) || '<color=#8A8A93>Utanför matcher: Discord-serverboostare betalas 2000g i månaden, och communityns konstnärer tjänar 30% i royalty (avrundat nedåt till helt guld) när en annan spelare köper deras föremål - gåvor betalar inget.</color>'),
        -- InfoLibrary WhenCounts (the rule book)
        ('9d365a214640aebd', 'es', 'd0ec9113911cb0e765862a792d3dc650658b6a0a', 'El reglamento de qué se registra y qué se tira: juegos, series, desconexiones, apuestas. Si un resultado parece perdido, la razón está casi siempre en esta página.' || chr(10) || chr(10) || '<color=#FFD94D><b>NUNCA REGISTRADO EN ABSOLUTO</b></color>' || chr(10) || chr(10) || '- Consentimiento de datos apagado: el mod corre totalmente offline. Nunca se envía nada salvo una comprobación de versión.' || chr(10) || '- Partidas offline, de práctica y sandbox: nunca las reporta el cliente, y el servidor las rechaza como respaldo.' || chr(10) || '- Los asientos de espectador no envían registro de partida ni estadísticas persistentes. (El mod guarda diagnósticos locales en su propio registro — frames, datos de conexión — y no envía nada automáticamente; solo salen de tu PC dentro de un reporte de bug al que decidas adjuntar los registros.)' || chr(10) || chr(10) || '<color=#FFD94D><b>RANKED O CASUAL</b></color>' || chr(10) || chr(10) || '- El interruptor Ranked de cualquiera de los dos apagado en una partida por código - se juega como CASUAL. Igualmente registrada con stats y XP; nunca toca rating (ver <color=#7FD4FF>Cómo se registran las partidas</color>).' || chr(10) || '- El rival nunca ha usado el mod - siempre casual, nunca se asciende. (Una serie viva sin terminar de una sesión anterior es lo único que conserva el estado ranked a través de un hueco.)' || chr(10) || '- Apagar Ranked A MITAD DE SERIE no anula la serie. El al-mejor-de-3 en marcha es tu registro de consentimiento; sus juegos siguen ranked.' || chr(10) || '- Un juego reportado como casual se ASCIENDE a ranked cuando el servidor puede ver que ambos jugadores tienen mod, ambos tienen Ranked activo y la sesión está viva.' || chr(10) || '- Un participante baneado de ranked fuerza un 1v1 casual al reportarse - incluso en sala de cola, incluso a mitad de serie. (Los otros modos cierran la puerta a los baneados directamente.)' || chr(10) || '- Las salas creadas por el mod llevan consentimiento por definición; encolar es consentir. La cola ranked, el 2v2 y los torneos puntúan; las salas FFA ranked puntúan y las casual no; 1v2 registra sin puntuar.' || chr(10) || chr(10) || '<color=#FFD94D><b>DESCONEXIONES - 1V1</b></color>' || chr(10) || chr(10) || '- Dejas una partida para entrar en un emparejamiento ranked en cola - la partida que dejaste se cancela: nada registrado, ningún abandono anotado.' || chr(10) || '- El rival se desconecta a 4-4 - te llevas la victoria, registrada 5-4.' || chr(10) || '- El rival se desconecta mientras tienes 4 rondas - te llevas la victoria con el marcador vigente.' || chr(10) || '- Cualquier otra DC - <color=#FF6666>el juego se cancela y no se registra resultado</color>, incluso cuando quien se fue iba por delante. Nadie recibe una victoria gratis y nadie traga una derrota injusta (el abandono en sí puede anotarse igualmente - ver abajo).' || chr(10) || '- % de abandono ranked: una DC se anota contra quien se fue cuando el juego ACTUAL tenía juego significativo (2 o más puntos anotados, o una ronda completada) y nadie estaba a 4 rondas. Una DC por jugador por serie. La stat es tus DCs divididas por tus series ranked jugadas más tus DCs.' || chr(10) || '- Rabietas casual: CUALQUIER salida a mitad de juego en un 1v1 casual se anota, incluso a 4-0. Alimenta la stat de % de rabietas (cuán a menudo los rivales te abandonan) - nunca el rating. (Un superviviente ya con 4 rondas se lleva igualmente la victoria casual y su XP.)' || chr(10) || chr(10) || '<color=#FFD94D><b>DESCONEXIONES - 2V2 Y FFA</b></color>' || chr(10) || chr(10) || '- 2v2: un equipo se desconecta mientras el otro lidera la serie y el juego abandonado tenía 2 o más puntos - el equipo líder se lleva la serie entera, con ratings y recompensas completos.' || chr(10) || '- Cualquier otra DC de 2v2 - la serie se PAUSA para resolución manual de admin en vez de autodecidirse. Si los mismos cuatro reencolan en unos 30 minutos, el emparejador los devuelve a la misma serie con el marcador conservado.' || chr(10) || '- FFA sigue jugando cuando alguien se va, mientras queden 2 o más (un juego que baja de 3 jugadores antes de que el campo anotara 2 medios puntos se cancela en su lugar). Los recuentos de quien se va se congelan, y aun así se le coloca y puntúa el juego que dejó - <color=#FF6666>irse a 0 puntos no esquiva la derrota</color>.' || chr(10) || '- Gracia de salida temprana FFA: quien se fue antes de que el campo anotara cuatro medios puntos en total, se hayan convertido o no en un punto completo, no puntúa ese juego ni recibe oro ni XP de él. Los logros y las demás formas de ganar no se ven afectados.' || chr(10) || '- Un jugador FFA que se fue en un juego ANTERIOR viaja en los reportes posteriores como ausente, excluido de los ratings y recompensas de esos juegos.' || chr(10) || chr(10) || '<color=#FFD94D><b>SERIES: REANUDAR, ESTANCARSE, CADUCAR</b></color>' || chr(10) || chr(10) || '- <color=#7FE87F>Un al-mejor-de-3 sin decidir se reanuda sin límite de tiempo.</color> Encuentra al mismo rival mañana o la semana que viene y el juego 1 sigue en pie. Una caducidad existió una vez - los desertores la esperaban para embolsarse el rating, así que se quitó.' || chr(10) || '- El rating se mueve SOLO al completarse una serie (primero a 2 juegos ganados). Los juegos de una serie que nunca se completa conservan sus filas de partida, XP y oro; el cambio de rating simplemente nunca ocurre.' || chr(10) || '- Una serie sin ningún juego registrado 30 minutos después de crearse se abandona y sus apuestas se devuelven.' || chr(10) || '- Un estancamiento de una hora a mitad de serie devuelve las apuestas, pero la serie sigue activa y reanudable.' || chr(10) || '- Las series de torneo están exentas de esta poda - el cuadro es dueño de su ciclo de vida. Una partida de torneo decidida por incomparecencia no puede apostarse.' || chr(10) || chr(10) || '<color=#FFD94D><b>DESCARTADO A POSTERIORI</b></color>' || chr(10) || chr(10) || '- La única invalidación AUTOMÁTICA de todo el mod: un patrón repetido de partidas implausiblemente cortas entre los mismos dos jugadores en una ventana corta. La partida actual Y las cortas anteriores se invalidan juntas, su oro y XP revertidos, sus series anuladas.' || chr(10) || '- Reversión de admin: un admin puede anular una serie - cambios de rating restados, oro recuperado, cada partida de ella invalidada, apuestas sin resolver devueltas. Las partidas invalidadas desaparecen de cada tabla y stat.' || chr(10) || '- Cuarentena (2v2 y FFA): un reporte que llega para una sala que ya no está activa no se borra - se retiene para revisión de admin, y un admin todavía puede aceptarlo al registro o descartarlo.' || chr(10) || chr(10) || '<color=#FFD94D><b>SI EL REPORTE NO PUEDE ENVIARSE</b></color>' || chr(10) || chr(10) || '- Un reporte fallido va a un buzón persistente: se reintenta en segundo plano y se guarda a disco, así que se reenvía en tu siguiente arranque aunque cierres justo después del juego. Verás ''El informe falló - se reintentará en segundo plano'', y luego ''Partida registrada'' cuando aterrice.' || chr(10) || '- El reportero de 1v1 se cuelga antes de existir el reporte - la vía de desconexión del rival superviviente suele registrar el resultado en su lugar.' || chr(10) || '- FFA elige a su reportero entre los presentes, así que un reportero colgado nunca sale elegido. Un ganador que se va antes del reporte se registra igualmente desde sus recuentos congelados.' || chr(10) || '- Un juego 2v2 que termina sin su id de serie reintenta la búsqueda y aplaza el envío; si eso también falla, el juego no se registra.'),
        ('9d365a214640aebd', 'ru', 'd0ec9113911cb0e765862a792d3dc650658b6a0a', 'Свод правил о том, что записывается, а что выбрасывается: игры, серии, дисконнекты, ставки. Если результат «пропал», причина почти всегда на этой странице.' || chr(10) || chr(10) || '<color=#FFD94D><b>НЕ ЗАПИСЫВАЕТСЯ ВООБЩЕ</b></color>' || chr(10) || chr(10) || '- Согласие на данные выключено: мод работает полностью офлайн. Не отправляется ничего, кроме проверки версии.' || chr(10) || '- Офлайн, практика и песочница: клиент их не отправляет никогда, а сервер на всякий случай отклоняет.' || chr(10) || '- Места зрителей не отправляют ни записи матча, ни постоянной статистики. (Мод ведёт локальную диагностику в собственном логе — кадры, данные о соединении — и не отправляет ничего автоматически; они покидают твой ПК только внутри репорта бага, к которому ты сам приложил логи.)' || chr(10) || chr(10) || '<color=#FFD94D><b>РЕЙТИНГ ИЛИ КАЗУАЛ</b></color>' || chr(10) || chr(10) || '- Ranked выключен у любого игрока в игре по коду - она играется КАЗУАЛЬНОЙ. Всё равно полностью записывается со статами и XP; рейтинг не трогает никогда (см. <color=#7FD4FF>Как отслеживаются игры</color>).' || chr(10) || '- Соперник никогда не запускал мод - всегда казуал, без апгрейда. (Живая незавершённая серия с прошлой сессии - единственное, что сохраняет рейтинговый статус через разрыв.)' || chr(10) || '- Выключение Ranked ПОСРЕДИ СЕРИИ серию не отменяет. Идущий best-of-3 - твоя запись согласия; его игры остаются рейтинговыми.' || chr(10) || '- Игра, отправленная казуальной, АПГРЕЙДИТСЯ до рейтинговой, когда сервер видит: оба на моде, у обоих Ranked включён и сессия живая.' || chr(10) || '- Участник с рейтинговым баном принуждает 1v1 к казуалу на момент отчёта - даже в комнате очереди, даже посреди серии. (Остальные режимы отсекают забаненных ещё на входе.)' || chr(10) || '- Комнаты мода согласованы по определению; очередь - это согласие. Рейтинговая очередь, 2v2 и турниры рейтингуют; рейтинговые лобби FFA рейтингуют, казуальные - нет; 1v2 записывается без рейтинга.' || chr(10) || chr(10) || '<color=#FFD94D><b>ДИСКОННЕКТЫ - 1V1</b></color>' || chr(10) || chr(10) || '- Ты выходишь из игры ради сматченного рейтингового матча - покинутая игра отменяется: ничего не записано, выход не отмечен.' || chr(10) || '- Соперник DC-нется при 4-4 - победа твоя, записывается 5-4.' || chr(10) || '- Соперник DC-нется, пока у тебя 4 раунда, - победа твоя при текущем счёте.' || chr(10) || '- Любой другой DC - <color=#FF6666>игра отменяется и результат не записывается</color>, даже если вышедший вёл. Никто не получает дармовую победу и никто не ест нечестное поражение (сам выход всё же может быть отмечен - см. ниже).' || chr(10) || '- Рейтинговый % выходов: DC записывается на вышедшего, когда в ТЕКУЩЕЙ игре была осмысленная игра (2 и более набранных очков или завершённый раунд) и ни одна сторона не была на 4 раундах. Один DC на игрока за серию. Стат - твои DC, делённые на твои сыгранные рейтинговые серии плюс твои DC.' || chr(10) || '- Казуальные рейдж-квиты: ЛЮБОЙ выход посреди казуального 1v1 отмечается, даже при 4-0. Он питает стат «% рейдж-квитов» (как часто соперники бросают тебя посреди игры) - никогда не рейтинг. (Выживший, уже имеющий 4 раунда, всё равно берёт казуальную победу и её XP.)' || chr(10) || chr(10) || '<color=#FFD94D><b>ДИСКОННЕКТЫ - 2V2 И FFA</b></color>' || chr(10) || chr(10) || '- 2v2: команда DC-нется, пока другая ведёт серию, а в брошенной игре было 2 и более очков, - ведущая команда берёт всю серию, с полным рейтингом и наградами.' || chr(10) || '- Любой другой DC в 2v2 - серия ставится на ПАУЗУ до ручного решения админа, а не решается сама. Если те же четверо перевстают в очередь в течение ~30 минут, матчер возвращает их на ту же серию с сохранённым счётом.' || chr(10) || '- FFA продолжает играть после чьего-то выхода, пока остаются 2 и более (игра, упавшая ниже 3 игроков до 2 набранных полем полуочков, вместо этого отменяется). Счёт вышедшего замораживается, и он всё равно получает место и рейтинг за игру, которую покинул, - <color=#FF6666>выход при 0 очков от поражения не уворачивается</color>.' || chr(10) || '- Льгота раннего выхода FFA: вышедший до того, как поле набрало в сумме четыре полуочка (ставшие полным очком или нет), не рейтингуется за ту игру и не получает за неё ни игрового золота, ни XP. Достижения и другие способы заработка не затрагиваются.' || chr(10) || '- Игрок FFA, вышедший в БОЛЕЕ РАННЕЙ игре, едет в поздних отчётах отсутствующим, вне рейтингов и наград тех игр.' || chr(10) || chr(10) || '<color=#FFD94D><b>СЕРИИ: ВОЗОБНОВЛЕНИЕ, СТОПОР, ИСТЕЧЕНИЕ</b></color>' || chr(10) || chr(10) || '- <color=#7FE87F>Нерешённый best-of-3 возобновляется без лимита времени.</color> Встреть того же соперника завтра или через неделю - игра 1 в силе. Истечение когда-то существовало - вышедшие пересиживали его, чтобы забанкать рейтинг, и его убрали.' || chr(10) || '- Рейтинг движется ТОЛЬКО на завершении серии (до 2 побед в играх). Игры серии, которая так и не завершится, сохраняют строки матчей, XP и золото; просто изменение рейтинга не происходит никогда.' || chr(10) || '- Серия без единой записанной игры через 30 минут после создания бросается, её ставки возвращаются.' || chr(10) || '- Часовой стопор посреди серии возвращает ставки, но сама серия остаётся активной и возобновимой.' || chr(10) || '- Турнирные серии из этой прополки исключены - их жизненным циклом владеет сетка. На турнирный матч, решённый техпоражением, поставить нельзя.' || chr(10) || chr(10) || '<color=#FFD94D><b>ВЫБРОШЕНО ЗАДНИМ ЧИСЛОМ</b></color>' || chr(10) || chr(10) || '- Единственная АВТОМАТИЧЕСКАЯ инвалидция во всём моде: повторяющийся паттерн неправдоподобно коротких матчей между одними и теми же двумя игроками в коротком окне. Текущий матч И ранние короткие инвалидируются вместе, их золото и XP откатываются, их серии обнуляются.' || chr(10) || '- Откат админом: админ может обнулить серию - изменения рейтинга вычтены, золото отозвано, каждый её матч инвалидирован, нерасчитанные ставки возвращены. Инвалидированные матчи исчезают со всех досок и статов.' || chr(10) || '- Карантин (2v2 и FFA): отчёт, пришедший на уже неактивное лобби, не удаляется - он придерживается для админ-ревью, и админ может принять его в запись или отбросить.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЕСЛИ ОТЧЁТ НЕ ОТПРАВЛЯЕТСЯ</b></color>' || chr(10) || chr(10) || '- Неудавшийся отчёт уходит в стойкую очередь на отправку: повторяется в фоне и сохраняется на диск, так что перешлётся при следующем запуске, даже если ты вышел сразу после игры. Ты увидишь «Не удалось записать матч - повторяем в фоне», затем «Матч записан», когда дойдёт.' || chr(10) || '- Репортёр 1v1 упал до появления отчёта - результат обычно записывает путь дисконнектов выжившего соперника.' || chr(10) || '- FFA выбирает репортёра среди ещё присутствующих, так что упавший репортёр не избирается никогда. Победитель, вышедший до отчёта, всё равно записывается из своих замороженных счётчиков.' || chr(10) || '- Игра 2v2, кончившаяся без id своей серии, повторяет поиск и откладывает отправку; если не выйдет и это, игра не записывается.'),
        ('9d365a214640aebd', 'uk', 'd0ec9113911cb0e765862a792d3dc650658b6a0a', 'Звід правил про те, що записується, а що викидається: ігри, серії, дисконекти, ставки. Якщо результату наче бракує, причина майже завжди на цій сторінці.' || chr(10) || chr(10) || '<color=#FFD94D><b>НЕ ЗАПИСУЄТЬСЯ ВЗАГАЛІ</b></color>' || chr(10) || chr(10) || '- Згоду на дані вимкнено: мод працює повністю офлайн. Не надсилається нічого, крім перевірки версії.' || chr(10) || '- Офлайн, тренування й пісочниця: клієнт їх не репортить ніколи, а сервер про всяк випадок відмовляє.' || chr(10) || '- Місця глядачів не надсилають ані запису матчу, ані постійної статистики. (Мод веде локальну діагностику у власному лозі — кадри, дані про з’єднання — і нічого не надсилає автоматично; вони покидають ваш ПК лише всередині баг-репорту, до якого ви самі вирішили додати логи.)' || chr(10) || chr(10) || '<color=#FFD94D><b>РЕЙТИНГОВА ЧИ ЗВИЧАЙНА</b></color>' || chr(10) || chr(10) || '- Вимкнений Ranked у будь-кого в грі за кодом кімнати - гра йде як ЗВИЧАЙНА. Усе одно повністю записується зі статистикою і XP; рейтинг не чіпає ніколи (див. <color=#7FD4FF>Як відстежуються ігри</color>).' || chr(10) || '- Суперник ніколи не запускав мод - завжди звичайна, ніколи не підвищується. (Жива незавершена серія з попередньої сесії - єдине, що зберігає рейтинговий статус через перерву.)' || chr(10) || '- Вимикання Ranked ПОСЕРЕД СЕРІЇ серію не скасовує. Поточний BO3 - це ваш запис згоди; його ігри лишаються рейтинговими.' || chr(10) || '- Гра, зарепорчена як звичайна, ПІДВИЩУЄТЬСЯ до рейтингової, коли сервер бачить, що обидва гравці з модом, у обох Ranked увімкнено і сесія жива.' || chr(10) || '- Учасник із рейтинговим баном примусово робить 1v1 звичайним у момент звіту - навіть у кімнаті черги, навіть посеред серії. (Інші режими натомість не пускають забанених ще на порозі.)' || chr(10) || '- Кімнати від мода узгоджені за визначенням; черга і є згода. Рейтингова черга, 2v2 і турніри рейтингують; рейтингові лобі FFA рейтингують, звичайні ні; 1v2 записує без рейтингу.' || chr(10) || chr(10) || '<color=#FFD94D><b>ДИСКОНЕКТИ - 1V1</b></color>' || chr(10) || chr(10) || '- Ви виходите з гри заради рейтингового матчу з черги - покинута гра скасовується: нічого не записано, вихід не залоговано.' || chr(10) || '- Суперник вилітає на 4-4 - перемога ваша, записується 5-4.' || chr(10) || '- Суперник вилітає, поки у вас 4 раунди, - перемога ваша з поточним рахунком.' || chr(10) || '- Будь-який інший DC - <color=#FF6666>гра скасовується й результат не записується</color>, навіть коли втікач вів у рахунку. Ніхто не отримує дармової перемоги й ніхто не ковтає несправедливої поразки (сам вихід усе одно може бути залогований - див. нижче).' || chr(10) || '- Рейтинговий % виходів: DC логовується проти втікача, коли в ПОТОЧНІЙ грі була змістовна гра (2 і більше набраних очок або дограний раунд) і жодна сторона не мала 4 раундів. Один DC на гравця за серію. Статистика - ваші DC, поділені на зіграні рейтингові серії плюс ваші DC.' || chr(10) || '- Звичайні рейдж-квіти: БУДЬ-ЯКИЙ вихід посеред гри у звичайному 1v1 логовується, навіть на 4-0. Він живить статистику Rage Quit % (як часто суперники йдуть від вас) - ніколи не рейтинг. (Вцілілий, що вже мав 4 раунди, все одно бере звичайну перемогу та її XP.)' || chr(10) || chr(10) || '<color=#FFD94D><b>ДИСКОНЕКТИ - 2V2 І FFA</b></color>' || chr(10) || chr(10) || '- 2v2: команда вилітає, поки інша веде в серії, а в покинутій грі було 2 і більше очок - команда-лідер бере всю серію з повними рейтингами й нагородами.' || chr(10) || '- Будь-який інший DC у 2v2 - серія стає на ПАУЗУ до ручного рішення адміністрації замість автовирішення. Якщо ті самі четверо стають у чергу знову протягом приблизно 30 хвилин, матчер повертає їх у ту саму серію зі збереженим рахунком.' || chr(10) || '- FFA грає далі, коли хтось виходить, поки лишається 2 і більше (гра, де стало менше 3 гравців до 2 набраних полем половинок очка, натомість скасовується). Показники втікача заморожуються, і він усе одно отримує місце й рейтинг за гру, під час якої вийшов, - <color=#FF6666>вихід на 0 очок поразки не уникає</color>.' || chr(10) || '- Пільга раннього виходу FFA: втікач, що вийшов до того, як поле набрало загалом чотири половинки очка (що стали повним очком чи ні), за ту гру не рейтингується й не отримує за неї ні ігрового золота, ні XP. Досягнення та інші способи заробітку лишаються без змін.' || chr(10) || '- Гравець FFA, що вийшов у ПОПЕРЕДНІЙ грі, їде в наступних звітах як відсутній, виключений з рейтингів і нагород тих ігор.' || chr(10) || chr(10) || '<color=#FFD94D><b>СЕРІЇ: ВІДНОВЛЕННЯ, СТОПОР, СПЛИВАННЯ</b></color>' || chr(10) || chr(10) || '- <color=#7FE87F>Невирішений BO3 відновлюється без обмеження часу.</color> Зустріньте того самого суперника завтра чи наступного тижня - гра 1 досі в силі. Строк колись існував - втікачі пересиджували його, щоб зберегти рейтинг, тож його прибрали.' || chr(10) || '- Рейтинг рухається ЛИШЕ коли серія завершується (до 2 виграних ігор). Ігри серії, що так і не завершилася, зберігають свої рядки матчів, XP і золото; просто зміна рейтингу не стається ніколи.' || chr(10) || '- Серія без жодної записаної гри через 30 хвилин після створення закидається, а її ставки повертаються.' || chr(10) || '- Годинний стопор посеред серії повертає ставки, але сама серія лишається активною й відновлюваною.' || chr(10) || '- Турнірні серії звільнені від цієї чистки - їхній життєвий цикл належить сітці. На турнірний матч, вирішений технічною поразкою, поставити не можна.' || chr(10) || chr(10) || '<color=#FFD94D><b>ВИКИНУТЕ ЗАДНІМ ЧИСЛОМ</b></color>' || chr(10) || chr(10) || '- Єдине АВТОМАТИЧНЕ анулювання в усьому моді: повторюваний шаблон неправдоподібно коротких матчів між тими самими двома гравцями в короткому вікні. Поточний матч І раніші короткі анулюються разом, їхні золото і XP повертаються, їхні серії скасовуються.' || chr(10) || '- Адмінське скасування: адмін може анулювати серію - зміни рейтингу віднімаються, золото стягується назад, кожен матч у ній анулюється, нерозраховані ставки повертаються. Анульовані матчі зникають з усіх дощок і статистик.' || chr(10) || '- Карантин (2v2 і FFA): звіт, що прибув для вже неактивного лобі, не видаляється - він тримається на розгляд адміністрації, і адмін ще може прийняти його в запис або відкинути.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЯКЩО ЗВІТ НЕ НАДСИЛАЄТЬСЯ</b></color>' || chr(10) || chr(10) || '- Невдалий звіт іде в постійну вихідну скриньку: повторюється у фоні й зберігається на диск, тож надсилається знову з наступним запуском, навіть якщо ви вийшли одразу після гри. Ви побачите «Не вдалося записати матч - повторюємо у фоні», а коли долетить - «Матч записано».' || chr(10) || '- Репортер 1v1 вилетів до того, як звіт існує, - результат зазвичай записує шлях дисконекту вцілілого суперника.' || chr(10) || '- FFA обирає репортера серед досі присутніх гравців, тож клієнт, що впав, репортером не стане. Переможець, що вийшов до звіту, все одно записується зі своїх заморожених показників.' || chr(10) || '- Гра 2v2, що закінчилася без id своєї серії, повторює пошук і відкладає надсилання; якщо не вдалося і це, гра не записується.'),
        ('9d365a214640aebd', 'sv', 'd0ec9113911cb0e765862a792d3dc650658b6a0a', 'Regelboken för vad som registreras och vad som kastas: matcher, serier, frånkopplingar, vad. Om ett resultat verkar saknas finns orsaken nästan alltid på den här sidan.' || chr(10) || chr(10) || '<color=#FFD94D><b>REGISTRERAS ALDRIG ALLS</b></color>' || chr(10) || chr(10) || '- Datasamtycke av: modden kör helt offline. Inget skickas någonsin utom en versionskontroll.' || chr(10) || '- Offline-, tränings- och sandbox-matcher: rapporteras aldrig av klienten, och nekas av servern som skyddsnät.' || chr(10) || '- Åskådarplatser skickar in ingen matchpost och ingen bestående statistik. (Modden sparar lokal diagnostik i sin egen logg — bildrutor, anslutningsfakta — och skickar inget automatiskt; den lämnar din dator bara inuti en buggrapport som du själv väljer att bifoga loggar till.)' || chr(10) || chr(10) || '<color=#FFD94D><b>RANKED ELLER CASUAL</b></color>' || chr(10) || chr(10) || '- Endera spelarens Ranked-växel av i en rumskodsmatch - den spelas som CASUAL. Fortfarande fullt registrerad med statistik och XP; den rör aldrig rating (se <color=#7FD4FF>Så registreras matcher</color>).' || chr(10) || '- Motståndaren har aldrig kört modden - alltid casual, uppgraderas aldrig. (En pågående oavslutad serie från en tidigare sittning är det enda som behåller Ranked-status över ett uppehåll.)' || chr(10) || '- Att slå av Ranked MITT I SERIEN ogiltigförklarar inte serien. Den pågående bäst-av-3:an är ditt samtyckesbevis; dess matcher förblir Ranked.' || chr(10) || '- En match som rapporterats som casual UPPGRADERAS till Ranked när servern kan se att båda spelarna är moddade, båda har Ranked på och sittningen är live.' || chr(10) || '- En Ranked-bannad deltagare tvingar en 1v1 till casual vid rapporttillfället - även i ett körum, även mitt i en serie. (De andra lägena stänger ute bannade spelare vid dörren i stället.)' || chr(10) || '- Modd-utfärdade rum är samtyckta per definition; att köa är samtycke. Ranked-kön, 2v2 och turneringar betygsätter; Ranked-FFA-lobbyer betygsätter medan casual-lobbyer inte gör det; 1v2 registrerar utan rating.' || chr(10) || chr(10) || '<color=#FFD94D><b>FRÅNKOPPLINGAR - 1V1</b></color>' || chr(10) || chr(10) || '- Du lämnar en match för att gå med i en köad Ranked-match - matchen du lämnade ställs in: inget registreras, inget avhopp loggas.' || chr(10) || '- Motståndaren kopplar från vid 4-4 - du får vinsten, registrerad 5-4.' || chr(10) || '- Motståndaren kopplar från medan du håller 4 ronder - du får vinsten med den stående ställningen.' || chr(10) || '- Varje annan frånkoppling - <color=#FF6666>matchen ställs in och inget resultat registreras</color>, även när den som lämnade låg i ledning. Ingen får en gratisvinst och ingen äter en orättvis förlust (själva avhoppet kan ändå loggas - se nedan).' || chr(10) || '- Ranked-avhoppsprocent: en DC loggas mot den som lämnade när den PÅGÅENDE matchen hade meningsfullt spel (2 eller fler gjorda poäng, eller en avslutad rond) och ingen sida stod på 4 ronder. En DC per spelare per serie. Statistiken är dina DC:er delat med dina spelade Ranked-serier plus dina DC:er.' || chr(10) || '- Casual-ragequits: VARJE avhopp mitt i en casual-1v1 loggas, även vid 4-0. Det matar Ragequit-%-statistiken (hur ofta motståndare går ifrån dig) - aldrig rating. (En överlevare som redan står på 4 ronder tar ändå casual-vinsten och dess XP.)' || chr(10) || chr(10) || '<color=#FFD94D><b>FRÅNKOPPLINGAR - 2V2 OCH FFA</b></color>' || chr(10) || chr(10) || '- 2v2: ett lag kopplar från medan det andra laget leder serien och den övergivna matchen hade 2 eller fler poäng - det ledande laget tar hela serien, med fulla ratingar och belöningar.' || chr(10) || '- Varje annan 2v2-DC - serien PAUSAS för manuell adminhantering i stället för att autoavgöras. Köar samma fyra om inom ungefär 30 minuter sätter matchningen tillbaka dem på samma serie med ställningen kvar.' || chr(10) || '- FFA fortsätter spela när någon lämnar, så länge 2 eller fler är kvar (en match som faller under 3 spelare innan fältet gjort 2 halvpoäng ställs in i stället). Avhopparens räkningar fryses, och de placeras och betygsätts ändå för matchen de lämnade under - <color=#FF6666>att lämna på 0 poäng undviker inte förlusten</color>.' || chr(10) || '- FFA:s respit vid tidigt avhopp: en avhoppare som lämnade innan fältet gjort fyra halvpoäng sammanlagt, oavsett om någon blivit en hel poäng, får ingen rating för den matchen och inget matchguld eller XP från den. Prestationer och andra sätt att tjäna påverkas inte.' || chr(10) || '- En FFA-spelare som lämnade i en TIDIGARE match följer med i senare rapporter som frånvarande, utesluten ur de matchernas ratingar och belöningar.' || chr(10) || chr(10) || '<color=#FFD94D><b>SERIER: ÅTERUPPTA, STANNA, GÅ UT</b></color>' || chr(10) || chr(10) || '- <color=#7FE87F>En oavgjord bäst-av-3 återupptas utan tidsgräns.</color> Möt samma motståndare imorgon eller nästa vecka och match 1 står kvar. En utgångstid fanns en gång - avhoppare väntade ut den för att banka rating, så den togs bort.' || chr(10) || '- Rating rör sig BARA när en serie avslutas (först till 2 matchvinster). Matcher i en serie som aldrig avslutas behåller sina matchrader, XP och guld; ratingförändringen sker bara aldrig.' || chr(10) || '- En serie utan registrerad match 30 minuter efter att den skapades överges och dess vad återbetalas.' || chr(10) || '- Ett stillestånd på en timme mitt i serien återbetalar vaden, men serien själv förblir aktiv och återupptagbar.' || chr(10) || '- Turneringsserier är undantagna den här gallringen - spelträdet äger deras livscykel. En turneringsmatch avgjord på walkover kan inte satsas på.' || chr(10) || chr(10) || '<color=#FFD94D><b>UTSLÄNGT I EFTERHAND</b></color>' || chr(10) || chr(10) || '- Den enda AUTOMATISKA ogiltigförklaringen i hela modden: ett upprepat mönster av orimligt korta matcher mellan samma två spelare inom ett kort fönster. Den aktuella matchen OCH de tidigare korta ogiltigförklaras tillsammans, deras guld och XP återförs, deras serier annulleras.' || chr(10) || '- Adminupphävande: en admin kan annullera en serie - ratingförändringar dras tillbaka, guld återkrävs, varje match i den ogiltigförklaras, oavgjorda vad återbetalas. Ogiltigförklarade matcher försvinner från varje tavla och statistik.' || chr(10) || '- Karantän (2v2 och FFA): en rapport som anländer för en lobby som inte längre är aktiv raderas inte - den hålls för admingranskning, och en admin kan fortfarande acceptera in den i registret eller kasta den.' || chr(10) || chr(10) || '<color=#FFD94D><b>OM RAPPORTEN INTE KAN SKICKAS</b></color>' || chr(10) || chr(10) || '- En misslyckad rapport går till en beständig utkorg: den försöker igen i bakgrunden och sparas till disk, så den skickas om vid nästa start även om du stänger direkt efter matchen. Du ser ''Kunde inte registrera matchen - försöker igen i bakgrunden'', sedan ''Match registrerad'' när den landar.' || chr(10) || '- 1v1-rapportören kraschar innan rapporten finns - den överlevande motståndarens frånkopplingsväg registrerar oftast resultatet i stället.' || chr(10) || '- FFA utser sin rapportör bland spelarna som fortfarande är kvar, så en kraschad rapportör utses aldrig. En vinnare som slutar före rapporten registreras ändå från sina frusna räkningar.' || chr(10) || '- En 2v2-match som slutar utan sitt serie-id försöker slå upp det igen och skjuter upp sändningen; misslyckas även det registreras matchen inte.'),
        -- ModeInfoText Ffa (the FFA mode text)
        ('0ab13f648dd0175b', 'es', 'd051e33ca0935879b78ca79817301c2f6bac8a06', 'Todos contra todos para 3-10 jugadores. Cada jugador es su propio equipo.' || chr(10) || 'Puntuación estándar de ROUNDS - el primero en llegar a {0} puntos gana el juego.' || chr(10) || chr(10) || '<color=#FFD94D><b>CÓMO JUGAR</b></color>' || chr(10) || chr(10) || '- No hay banda de Elo. Entrar en una sala es consentir jugar.' || chr(10) || chr(10) || '- Crea una sala, o únete a una abierta desde el buscador.' || chr(10) || '  El ANFITRIÓN pulsa Empezar cuando hay al menos 3' || chr(10) || '  jugadores (hasta 10). Puede haber varias salas abiertas.' || chr(10) || chr(10) || '- Si el anfitrión se va, el miembro que más lleva' || chr(10) || '  esperando pasa a ser el nuevo anfitrión automáticamente.' || chr(10) || chr(10) || '- Tras cada punto, todos menos el ganador del punto' || chr(10) || '  eligen una carta a la vez.' || chr(10) || chr(10) || '- El temporizador de elección se ve en pantalla. Una' || chr(10) || '  elección cerca del final da a todos algo de tiempo' || chr(10) || '  extra. Cuando tu temporizador llega a cero, tu carta' || chr(10) || '  resaltada se elige sola - alejarte del teclado nunca' || chr(10) || '  se salta tu elección. Solo una elección que pierde la' || chr(10) || '  ventana por completo (una congelación, un cuelgue o el' || chr(10) || '  último instante) queda sin carta, con un aviso que lo dice.' || chr(10) || chr(10) || '- Llevas hasta {1} cartas.' || chr(10) || '  Elegir una más reemplaza tu carta más antigua.' || chr(10) || chr(10) || '<color=#FFD94D><b>AJUSTES DEL ANFITRIÓN</b></color>' || chr(10) || chr(10) || '- El anfitrión puede afinar la sala antes de empezar:' || chr(10) || '  objetivo de puntos (3-10), robos iniciales, cartas' || chr(10) || '  ofrecidas por robo (1-5), máximo de cartas (3-5 ranked,' || chr(10) || '  hasta 6 casual), la regla de Mismas cartas y ranked/casual.' || chr(10) || chr(10) || '- Regla de Mismas cartas: el robo N de todos ofrece los' || chr(10) || '  MISMOS candidatos, en el mismo orden - si a ti y a un' || chr(10) || '  rival os ofrecieron cartas idénticas todo el juego,' || chr(10) || '  ningún resultado puede achacarse a la suerte del robo.' || chr(10) || '  Las cartas de una copia (como Phoenix) aparecen como' || chr(10) || '  mucho una vez por juego para todos.' || chr(10) || chr(10) || '- Tras un cambio de ajustes la sala no puede empezar en' || chr(10) || '  60 segundos (y un momento tras entrar alguien nuevo),' || chr(10) || '  para que todos lean lo que cambió. Las salas casual' || chr(10) || '  pagan recompensas reducidas y nunca tocan ratings.' || chr(10) || chr(10) || '<color=#FFD94D><b>RATING</b></color>' || chr(10) || chr(10) || '- FFA es ranked con su propio rating Glicko.' || chr(10) || chr(10) || '- El puesto usa puntos, luego todas las rondas ganadas' || chr(10) || '  (las gastadas incluidas), luego kills.' || chr(10) || '  Los empates restantes comparten puesto en orden de' || chr(10) || '  competición: 1, 2, 2, 4.' || chr(10) || chr(10) || '- Tu rating se puntúa contra los jugadores colocados' || chr(10) || '  más cerca de ti (hasta 4), así que un juego no puede' || chr(10) || '  sacudir tu rating varias veces más fuerte en una sala' || chr(10) || '  de 10 que en una de 3. Una comparación extra puede' || chr(10) || '  unirse a esas cuatro: la mayor diferencia de rating de' || chr(10) || '  250+ que terminó al revés fuera de ellas.' || chr(10) || chr(10) || '- Un puesto empatado cuenta como empate. Los ratings' || chr(10) || '  nuevos se mueven rápido y se asientan al jugar más.' || chr(10) || chr(10) || '<color=#FFD94D><b>RECOMPENSAS</b></color>' || chr(10) || chr(10) || '- El pago se mide por la PELEA, no por números planos' || chr(10) || '  por juego: las rondas decisivas son la unidad de' || chr(10) || '  trabajo, y el tiempo transcurrido limita lo rápido que' || chr(10) || '  se cobran - las tácticas de estancamiento quedan' || chr(10) || '  acotadas, y los juegos más largos y grandes pagan más.' || chr(10) || chr(10) || '- Las salas más grandes pagan mejor tasa por minuto, y' || chr(10) || '  un FFA de 10 jugadores es la mejor tasa de oro del juego.' || chr(10) || chr(10) || '- Tu puesto da forma a tu parte: el 1.º gana unas cinco' || chr(10) || '  veces el recorte del último. Parte se paga como XP,' || chr(10) || '  parte como Oro de puesto, y un campo rival más fuerte' || chr(10) || '  multiplica el bote (el bonus de rango habitual).' || chr(10) || chr(10) || '- El XP se convierte en oro a 100 XP = 1 de oro, y las' || chr(10) || '  subidas de nivel pagan su oro extra habitual. Una' || chr(10) || '  subida durante un juego aparece dentro del +g de ese' || chr(10) || '  juego - así es como un último puesto puede a veces' || chr(10) || '  ganar más que el vencedor.' || chr(10) || chr(10) || '- Los espectadores pueden apostar oro en salas FFA desde' || chr(10) || '  esta pestaña.' || chr(10) || chr(10) || '<color=#FFD94D><b>LEER LA LISTA DE FFAS RECIENTES</b></color>' || chr(10) || chr(10) || '<color=#7FD4FF>Círculos + N(P)</color> - Puntos completos ganados.' || chr(10) || '<color=#7FD4FF>Medios círculos + N(H)</color> - Rondas ganadas' || chr(10) || '  que no se volvieron uno de sus puntos completos.' || chr(10) || '<color=#7FD4FF>Nk</color> - Kills.' || chr(10) || '<color=#7FD4FF>+xp +g</color> - El XP y oro de ese juego' || chr(10) || '  (incluido cualquier bonus de subida de nivel).' || chr(10) || '<color=#7FD4FF>Número verde/rojo</color> - Cambio de rating FFA.' || chr(10) || '<color=#7FD4FF>Cartas</color> - La mano al terminar el juego.' || chr(10) || '  <color=#FF6666>+N reemplazadas</color> cuenta elecciones que' || chr(10) || '  el tope de cartas expulsó - pasa el cursor por la línea' || chr(10) || '  para ver cada elección en orden.' || chr(10) || chr(10) || '<color=#FFD94D><b>COLUMNAS DE LA CLASIFICACIÓN</b></color>' || chr(10) || chr(10) || '<color=#7FD4FF>Rank</color> - Posición en el orden seleccionado.' || chr(10) || '<color=#7FD4FF>Player</color> - El nombre visible del jugador.' || chr(10) || '<color=#7FD4FF>Rating</color> - El rating Glicko FFA separado del jugador.' || chr(10) || '<color=#7FD4FF>Games</color> - Juegos FFA registrados.' || chr(10) || '<color=#7FD4FF>Wins</color> - Juegos terminados en 1.er puesto.' || chr(10) || '<color=#7FD4FF>Top3</color> - Juegos terminados 1.º, 2.º o 3.º.' || chr(10) || '<color=#7FD4FF>AvgPl</color> - Puesto medio final. Menos es' || chr(10) || '  mejor - 1.0 significa ganarlo todo.' || chr(10) || '<color=#7FD4FF>WR</color> - Parte de juegos ganados limpiamente.' || chr(10) || chr(10) || '<color=#FFD94D><b>OJO CON ESTO</b></color>' || chr(10) || chr(10) || '- Salir a mitad de juego se registra. Quien se va' || chr(10) || '  conserva sus recuentos y se le coloca y puntúa el juego' || chr(10) || '  que dejó - salvo que se fuera antes de que el campo' || chr(10) || '  anotara cuatro medios puntos en total, se hayan' || chr(10) || '  convertido o no en un punto completo, en cuyo caso ese' || chr(10) || '  juego no lo puntúa ni le da oro ni XP. Los logros y' || chr(10) || '  las demás formas de ganar no se ven afectados.'),
        ('0ab13f648dd0175b', 'ru', 'd051e33ca0935879b78ca79817301c2f6bac8a06', 'Каждый сам за себя, 3-10 игроков. Каждый - своя команда.' || chr(10) || 'Обычный счёт ROUNDS - игру берёт первый с {0} очками.' || chr(10) || chr(10) || '<color=#FFD94D><b>КАК ИГРАТЬ</b></color>' || chr(10) || chr(10) || '- Диапазона Elo нет. Вход в лобби - согласие играть.' || chr(10) || chr(10) || '- Создай лобби или войди в открытое из списка.' || chr(10) || '  ХОСТ жмёт Старт, когда внутри хотя бы 3 игрока' || chr(10) || '  (до 10). Открытых лобби может быть несколько.' || chr(10) || chr(10) || '- Если хост уходит, новым хостом автоматически' || chr(10) || '  становится тот, кто ждёт дольше всех.' || chr(10) || chr(10) || '- После каждого очка все, кроме взявшего очко,' || chr(10) || '  выбирают карту одновременно.' || chr(10) || chr(10) || '- Таймер выбора виден на экране. Пик под самый' || chr(10) || '  конец даёт всем немного больше времени.' || chr(10) || '  Когда твой таймер доходит до нуля, подсвеченная' || chr(10) || '  карта выбирается за тебя автоматически - отойти' || chr(10) || '  от клавиатуры не значит пропустить пик. Без' || chr(10) || '  карты остаётся только пик, целиком не успевший' || chr(10) || '  в окно (фриз, краш или самый последний миг), -' || chr(10) || '  об этом придёт уведомление.' || chr(10) || chr(10) || '- Ты держишь до {1} карт.' || chr(10) || '  Следующий пик заменяет самую старую карту.' || chr(10) || chr(10) || '<color=#FFD94D><b>НАСТРОЙКИ ХОСТА</b></color>' || chr(10) || chr(10) || '- До старта хост может настроить лобби: цель по' || chr(10) || '  очкам (3-10), стартовые доборы, число карт в' || chr(10) || '  раздаче (1-5), лимит карт на руках (3-5 в' || chr(10) || '  рейтинге, до 6 в казуале), правило «Те же карты»' || chr(10) || '  и рейтинг/казуал.' || chr(10) || chr(10) || '- Правило «Те же карты»: N-я раздача у всех' || chr(10) || '  предлагает ОДНИ И ТЕ ЖЕ карты в одном порядке -' || chr(10) || '  если вам с соперником всю игру давали одинаковые' || chr(10) || '  карты, итог не спишешь на удачу раздачи. Карты в' || chr(10) || '  одном экземпляре (например Phoenix) выпадают' || chr(10) || '  максимум раз за игру - на всех.' || chr(10) || chr(10) || '- После смены настроек лобби 60 секунд не может' || chr(10) || '  стартовать (и недолго после входа новичка), чтобы' || chr(10) || '  все успели прочитать изменения. Казуальные лобби' || chr(10) || '  платят меньше и не трогают рейтинг.' || chr(10) || chr(10) || '<color=#FFD94D><b>РЕЙТИНГ</b></color>' || chr(10) || chr(10) || '- FFA - рейтинговый режим со своим рейтингом Glicko.' || chr(10) || chr(10) || '- Место считают по очкам, потом по всем выигранным' || chr(10) || '  раундам (включая потраченные), потом по убийствам.' || chr(10) || '  Оставшиеся ничьи делят место по спортивному' || chr(10) || '  порядку: 1, 2, 2, 4.' || chr(10) || chr(10) || '- Твой рейтинг считается против ближайших к тебе по' || chr(10) || '  месту игроков (до 4), так что одна игра в лобби на' || chr(10) || '  10 человек не качнёт рейтинг в разы сильнее, чем в' || chr(10) || '  лобби на 3. К этой четвёрке может добавиться одно' || chr(10) || '  сравнение: крупнейший разрыв рейтинга в 250+,' || chr(10) || '  закончившийся вверх ногами вне них.' || chr(10) || chr(10) || '- Равное место считается ничьёй. Новый рейтинг' || chr(10) || '  двигается быстро и успокаивается с опытом.' || chr(10) || chr(10) || '<color=#FFD94D><b>НАГРАДЫ</b></color>' || chr(10) || chr(10) || '- Оплата меряется по БОРЬБЕ, а не по плоским суммам' || chr(10) || '  за игру: единица работы - решающие раунды, а' || chr(10) || '  прошедшее время ограничивает скорость их оплаты -' || chr(10) || '  затяжка даёт лишь ограниченный выигрыш, а долгие' || chr(10) || '  крупные игры платят больше.' || chr(10) || chr(10) || '- Большие лобби платят лучше в пересчёте на минуту,' || chr(10) || '  а FFA на 10 игроков - лучший курс золота в игре.' || chr(10) || chr(10) || '- Место определяет долю: 1-е получает примерно' || chr(10) || '  впятеро больше последнего. Часть платится как XP,' || chr(10) || '  часть - как золото за место, а сильные соперники' || chr(10) || '  умножают банк (обычный бонус за тир).' || chr(10) || chr(10) || '- XP меняется на золото по курсу 100 XP = 1 золото, а' || chr(10) || '  новые уровни платят свой обычный бонус. Уровень,' || chr(10) || '  взятый прямо в игре, попадает в её +g - вот почему' || chr(10) || '  последнее место иногда зарабатывает больше' || chr(10) || '  победителя.' || chr(10) || chr(10) || '- Зрители могут ставить золото на лобби FFA с этой' || chr(10) || '  вкладки.' || chr(10) || chr(10) || '<color=#FFD94D><b>КАК ЧИТАТЬ СПИСОК НЕДАВНИХ FFA</b></color>' || chr(10) || chr(10) || '<color=#7FD4FF>Точки + N(P)</color> - Взятые полные очки.' || chr(10) || '<color=#7FD4FF>Полуточки + N(H)</color> - Выигранные раунды,' || chr(10) || '  не ставшие полными очками этого игрока.' || chr(10) || '<color=#7FD4FF>Nk</color> - Убийства.' || chr(10) || '<color=#7FD4FF>+xp +g</color> - XP и золото этой игры' || chr(10) || '  (включая любой бонус за уровень).' || chr(10) || '<color=#7FD4FF>Зелёное/красное число</color> - Изменение рейтинга FFA.' || chr(10) || '<color=#7FD4FF>Карты</color> - Рука на конец игры.' || chr(10) || '  <color=#FF6666>+N заменено</color> считает пики, вытесненные' || chr(10) || '  лимитом карт, - наведись на строку, чтобы увидеть' || chr(10) || '  каждый пик по порядку.' || chr(10) || chr(10) || '<color=#FFD94D><b>СТОЛБЦЫ ТАБЛИЦЫ</b></color>' || chr(10) || chr(10) || '<color=#7FD4FF>Rank</color> - Позиция в выбранной сортировке.' || chr(10) || '<color=#7FD4FF>Player</color> - Отображаемое имя игрока.' || chr(10) || '<color=#7FD4FF>Rating</color> - Отдельный рейтинг Glicko для FFA.' || chr(10) || '<color=#7FD4FF>Games</color> - Записанные игры FFA.' || chr(10) || '<color=#7FD4FF>Wins</color> - Игры, законченные на 1-м месте.' || chr(10) || '<color=#7FD4FF>Top3</color> - Игры, законченные 1-м, 2-м или 3-м.' || chr(10) || '<color=#7FD4FF>AvgPl</color> - Среднее финишное место. Меньше -' || chr(10) || '  лучше: 1.0 значит победу в каждой игре.' || chr(10) || '<color=#7FD4FF>WR</color> - Доля игр, выигранных начисто.' || chr(10) || chr(10) || '<color=#FFD94D><b>НЮАНСЫ</b></color>' || chr(10) || chr(10) || '- Выход посреди игры записывается. Вышедший' || chr(10) || '  сохраняет свой счёт и получает место и рейтинг за' || chr(10) || '  игру, которую покинул, - если только не вышел до' || chr(10) || '  того, как поле набрало в сумме четыре полуочка' || chr(10) || '  (ставшие полным очком или нет): тогда та игра его' || chr(10) || '  не рейтингует и не платит ему ни игрового золота,' || chr(10) || '  ни XP. Достижения и другие способы заработка не' || chr(10) || '  затрагиваются.'),
        ('0ab13f648dd0175b', 'uk', 'd051e33ca0935879b78ca79817301c2f6bac8a06', 'Кожен сам за себе, 3-10 гравців. Кожен гравець - окрема команда.' || chr(10) || 'Звичайний рахунок ROUNDS - гру бере перший, хто набере {0} очок.' || chr(10) || chr(10) || '<color=#FFD94D><b>ЯК ГРАТИ</b></color>' || chr(10) || chr(10) || '- Діапазону Elo немає. Вхід у лобі - згода грати.' || chr(10) || chr(10) || '- Створіть лобі або увійдіть у відкрите зі списку.' || chr(10) || '  ХОСТ натискає «Почати», щойно є щонайменше 3 гравці' || chr(10) || '  (до 10). Одночасно може бути кілька відкритих лобі.' || chr(10) || chr(10) || '- Якщо хост іде, новим хостом автоматично стає' || chr(10) || '  той, хто чекає найдовше.' || chr(10) || chr(10) || '- Після кожного очка всі, крім того, хто його взяв,' || chr(10) || '  обирають карту одночасно.' || chr(10) || chr(10) || '- Таймер вибору видно на екрані. Вибір під самий' || chr(10) || '  кінець дає всім трохи додаткового часу.' || chr(10) || '  Коли ваш таймер сягне нуля, підсвічену карту буде' || chr(10) || '  обрано за вас автоматично - відійти від клавіатури' || chr(10) || '  не означає пропустити вибір. Без карти лишає тільки' || chr(10) || '  вибір, що зовсім не втрапив у вікно (зависання,' || chr(10) || '  краш або остання частка секунди), - зі сповіщенням' || chr(10) || '  про це.' || chr(10) || chr(10) || '- Ви тримаєте до {1} карт.' || chr(10) || '  Ще один вибір замінює вашу найстарішу карту.' || chr(10) || chr(10) || '<color=#FFD94D><b>НАЛАШТУВАННЯ ХОСТА</b></color>' || chr(10) || chr(10) || '- До старту хост може налаштувати лобі: ціль за' || chr(10) || '  очками (3-10), стартові роздачі, карт у роздачі' || chr(10) || '  (1-5), ліміт карт на руках (3-5 рейтингові, до 6' || chr(10) || '  звичайні), правило «Ті самі карти» та режим:' || chr(10) || '  Ranked або звичайний.' || chr(10) || chr(10) || '- Правило «Ті самі карти»: N-та роздача у всіх' || chr(10) || '  пропонує ТІ САМІ карти в тому самому порядку -' || chr(10) || '  якщо вам і